L["A big number in the middle of your screen counts down any pull your group starts, in place of the game's bar. Move it in unlock mode. In a dungeon or raid the game may keep its own bar for a countdown someone else starts."] = "Un grand nombre au milieu de l'écran décompte chaque pull lancé par votre groupe, à la place de la barre du jeu. Déplacez-le en mode déverrouillage. En donjon ou en raid, le jeu peut garder sa propre barre pour un compte à rebours lancé par quelqu'un d'autre."
L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "Un oiseau sur la carte du monde à chaque maître de vol utilisable : bleu pour l'Alliance, rouge pour la Horde, doré pour les deux."
L["A border and shadow around each line."] = "Une bordure et une ombre autour de chaque ligne."
