L["A border and shadow around the panel behind the bar. When off, the panel is a plain fill."] = "Une bordure et une ombre autour du panneau derrière la barre. Désactivé, le panneau est un simple aplat."
L["A border and shadow around the second meter's window."] = "Une bordure et une ombre autour de la fenêtre du second compteur."
L["A bright line along the cooldown shade's moving edge."] = "Une ligne lumineuse le long du bord mobile de l'ombrage du temps de recharge."
L["A buff's exact name"] = "Le nom exact d'une amélioration"
L["A buff's time turns orange and gently pulses in its last 5 seconds."] = "La durée d'une amélioration devient orange et pulse doucement pendant ses 5 dernières secondes."
L["A button on the game's class trainer window that learns every spell you can afford in one click. The DaylightUI style NPC window's trainer page has its own, so this is for the game's window (NPC window > Trainer window off)."] = "Un bouton dans la fenêtre du maître de classe du jeu qui apprend en un clic tous les sorts que vous pouvez payer. La page Maître de la fenêtre des PNJ de DaylightUI a le sien ; celui-ci est donc pour la fenêtre du jeu (Fenêtre des PNJ > Fenêtre du maître désactivée)."
L["A clean chat panel with class colors, timestamps and copyable links."] = "Un panneau de discussion épuré avec couleurs de classe, horodatage et liens copiables."
L["A color over the icon while the mouse is over it."] = "Une couleur sur l'icône pendant le survol."
L["A color over the icon while you press it."] = "Une couleur sur l'icône pendant que vous appuyez dessus."
L["A copy of the one in use, layout and all."] = "Une copie de celui en cours, disposition comprise."
L["A countdown icon for each totem you have down."] = "Une icône avec compte à rebours pour chaque totem posé."
L["A crown on top of the portrait ring (or over the name tab) for the party or raid leader."] = "Une couronne au-dessus de l'anneau du portrait (ou de l'onglet du nom) pour le chef de groupe ou de raid."
L["A dark edge around the letters on DaylightUI's frames, so text stays readable over a busy world."] = "Un bord sombre autour des lettres sur les cadres de DaylightUI, pour que le texte reste lisible sur un décor chargé."
L["A dash ( - )"] = "Un tiret ( - )"
L["A debuff you can remove, as tiles show it."] = "Un affaiblissement que vous pouvez dissiper, tel que les tuiles l'affichent."
L["A done objective stays, dimmed with a tick. When off, it disappears once it's done."] = "Un objectif accompli reste affiché, atténué et coché. Désactivé, il disparaît une fois accompli."
L["A dot ( · )"] = "Un point ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "Un dragon enroulé autour de l'extrémité de la barre d'un élite ou d'un boss, doré, ou argenté pour un rare."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "Un cadre déposé en mode déverrouillage, un sort placé dans l'éditeur du gestionnaire de temps de recharge, un clic-sort assigné. Le jeu n'a pas de son propre pour ces actions."
L["A framed panel behind the bar."] = "Un panneau encadré derrière la barre."
L["A friendly player's <guild> under their name, smaller."] = "La <guilde> d'un joueur allié sous son nom, en plus petit."
L["A gradient per point (Gradients page)"] = "Un dégradé par point (page Dégradés)"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Un mince trait vert sur la barre de vie pour les soins en cours, comme sur les cadres d'unité."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "Une victime ou un objet de quête s'affiche un instant en haut de l'écran, en petit, avec une barre de progression. Désactivez pour voir à la place la ligne jaune du jeu. Déplacez-le en mode déverrouillage."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "Une ligne sur les barres de vie ennemies là où vos coups de grâce deviennent utilisables. La fin de la barre jusqu'à cette ligne s'allume dans votre couleur d'accent quand l'ennemi est assez bas. Votre classe : guerriers (Exécution) et paladins (Marteau de courroux)."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "Une barre de mana, de rage ou d'énergie sous la vie. Désactivé, le cadre n'affiche que la vie."
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "Une marque juste à gauche de la barre de tout ce dont vos quêtes ont encore besoin. Pas en instance."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "Un marqueur au-dessus de la quête choisie et un chemin au sol qui y mène. Avec l'addon QuestieDB, une flèche vers l'objectif le plus proche en plus."
L["A member's border turns red while something is attacking them."] = "La bordure d'un membre devient rouge pendant que quelque chose l'attaque."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "L'anneau d'un membre (ou l'onglet du nom sans portrait) devient rouge pendant que quelque chose l'attaque."
L["A name for the new group:"] = "Un nom pour le nouveau groupe :"
L["A name for the new profile (a copy of %s):"] = "Un nom pour le nouveau profil (une copie de %s) :"
L["A new profession"] = "Un nouveau métier"
L["A new profile, made from %s with your picks."] = "Un nouveau profil, créé à partir de %s avec vos choix."
L["A new whisper shows its first words above the tiles for a few seconds. Click it to answer."] = "Un nouveau chuchotement affiche ses premiers mots au-dessus des tuiles pendant quelques secondes. Cliquez dessus pour répondre."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "Le nom d'une nouvelle zone apparaît en haut de l'écran avec une fine ligne dessous, puis la sous-zone et le statut JcJ ; une sous-zone n'affiche que son nom, en petit. Remplace le texte de zone du jeu. Suit les Effets de mouvement (Général > Apparence)."
