L["A panel behind the whole bar, so its buttons sit on one strip."] = "Un panneau derrière toute la barre, pour que ses boutons reposent sur une même bande."
L["A panel behind the whole bar."] = "Un panneau derrière toute la barre."
L["A player's <guild> under their name, smaller."] = "La <guilde> d'un joueur sous son nom, en plus petit."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "Les incantations d'un joueur dans la couleur de sa classe, ou le dégradé de sa classe avec un remplissage bicolore. Les incantations des créatures gardent le style de remplissage. Pas avec le dégradé Daylight."
L["A player's name in their class color; other units in their reaction's color."] = "Le nom d'un joueur dans la couleur de sa classe ; les autres unités dans la couleur de leur réaction."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "L'icône d'un bouton enfoncé s'abaisse légèrement et rebondit quand vous le relâchez."
L["A profile per character or talent set, and a share string for your whole setup."] = "Un profil par personnage ou jeu de talents, et un texte à partager pour toute votre configuration."
L["A pulsing border while the spell's proc alert is up."] = "Une bordure qui pulse pendant l'alerte de déclenchement du sort."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "Une quête prête à être rendue n'affiche que son titre. Une quête chronométrée n'est jamais repliée."
L["A quest you've failed, like a timed one that ran out."] = "Une quête échouée, comme une quête chronométrée dont le temps est écoulé."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "Un anneau sur l'extrémité extérieure. Icônes de classe pour les joueurs ; les PNJ montrent leur visage. Nécessite un cadre d'au moins 20 de hauteur."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "Un badge rond avec leur portrait, ou une barre fine avec le portrait à côté et le nom au-dessus."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "Un second compteur de dégâts dans sa propre fenêtre, pour deux listes à la fois : les soins à côté des dégâts, par exemple. Survolez-le pour les mêmes boutons."
L["A set already has that name."] = "Un ensemble porte déjà ce nom."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "Un bouclier : la barre se vide à mesure qu'il absorbe les dégâts, avec la quantité restante affichée. Ou selon sa durée, comme toute amélioration."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "Une compétence qui progresse affiche son nouveau rang sur son maximum : Couture 152 / 225. Les progressions suivantes mettent à jour la même ligne."
L["A slash ( / )"] = "Une barre oblique ( / )"
L["A slim bar under the tooltip of a player or creature."] = "Une barre fine sous l'infobulle d'un joueur ou d'une créature."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "Un emplacement à cette durabilité ou moins reçoit un point ambre et indique « Réparer bientôt »."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "Un petit LqE (lié quand équipé) ou LqU (lié quand utilisé) dans le coin supérieur gauche des objets en banque, jusqu'à ce que l'objet vous soit lié."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "Un petit LqE (lié quand équipé) ou LqU (lié quand utilisé) dans le coin supérieur gauche, jusqu'à ce que l'objet vous soit lié."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "Un petit LqE (lié quand équipé) ou LqU (lié quand utilisé) dans le coin supérieur gauche, jusqu'à ce que l'objet soit lié."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "Un petit bouton Copier en haut à droite de la discussion. Il ouvre le texte de l'onglet pour que vous puissiez le sélectionner et appuyer sur Ctrl+C. /dui copy fait de même."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "Un petit badge au pied du portrait (ou dans le coin du cadre sans portrait), coloré selon la difficulté de l'unité pour vous."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "Un petit badge au pied du portrait, coloré selon la difficulté de l'unité pour vous. Nécessite le portrait ou l'onglet du nom."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "Une petite barre à côté de chaque membre du groupe dont le familier est sorti. Votre propre familier garde son propre cadre."
L["A small crown on the raid leader's tile."] = "Une petite couronne sur la tuile du chef de raid."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "Un petit onglet couronne à côté de vos cadres de groupe ou de raid quand vous menez le groupe ou êtes assistant en raid. Il donne accès à l'appel, la vérification des rôles, un minuteur de pull, les marqueurs de cible et de terrain, et « Tous assistants ». Désactivé, ces outils ne sont accessibles que par les commandes slash du jeu."
L["A small dot in front of each quest you're tracking."] = "Un petit point devant chaque quête suivie."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "Un petit point dans le coin supérieur droit des objets en banque faisant partie d'un de vos ensembles d'équipement."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "Un petit point dans le coin supérieur droit des objets faisant partie d'un de vos ensembles d'équipement."
L["A small number in your accent color after a tab's name: how many new messages landed in it since you last looked."] = "Un petit nombre de votre couleur d'accent après le nom d'un onglet : combien de nouveaux messages y sont arrivés depuis votre dernier passage."
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "Une petite ligne grise en bas des infobulles de sorts et d'objets avec leur ID : pratique pour les macros, les autres addons et les rapports de bugs. Les icônes d'améliorations et d'affaiblissements utilisent l'infobulle du jeu, qui ne peut pas l'afficher."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "Une petite icône dans un coin pour un affaiblissement que vous pouvez dissiper, bordée de la couleur de son type."
L["A small mana, rage or energy number on the power bar."] = "Un petit nombre de mana, de rage ou d'énergie sur la barre de ressource."
L["A small pet bar beside each party member whose pet is out."] = "Une petite barre de familier à côté de chaque membre du groupe dont le familier est sorti."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "Un petit crâne sur le portrait dès que vos dégâts sur la durée suffisent à achever la cible."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "Un petit crâne après l'extrémité de la barre dès que vos dégâts sur la durée suffisent à achever cet ennemi."
L["A small soft drop shadow under text."] = "Une petite ombre portée douce sous le texte."
L["A small speech bubble at the top-right of the chat that counts your unread whispers and opens all your conversations. /dui whispers does the same."] = "Une petite bulle en haut à droite de la discussion qui compte vos chuchotements non lus et ouvre toutes vos conversations. /dui whispers fait de même."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "Un petit carré à gauche du cadre : rouge quand votre familier est malheureux, jaune quand il est satisfait, vert quand il est heureux. Survolez-le pour ses dégâts, sa loyauté et son régime."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "Une petite étiquette après le titre d'une quête élite, de donjon, de raid ou JcJ, ici et dans le journal des quêtes sur la carte."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "Une petite heure en bas de la carte. Survolez-la pour l'heure locale et l'heure du serveur."
L["A small zone name over each group of quests, the zone you're in first."] = "Un petit nom de zone au-dessus de chaque groupe de quêtes, celle où vous êtes en premier."
L["A soft chime when talents are applied, a talent set is switched, a spell is learned at a trainer or a letter is sent."] = "Un carillon doux quand des talents sont appliqués, qu'un jeu de talents est changé, qu'un sort est appris auprès d'un maître ou qu'une lettre est envoyée."
L["A soft glow behind a message that says your name or one of your words."] = "Une douce lueur derrière un message qui contient votre nom ou l'un de vos mots."
L["A soft glow in the threat color around the health bar."] = "Une lueur douce dans la couleur de menace autour de la barre de vie."
L["A soft light behind the arrow, in its color."] = "Une lumière douce derrière la flèche, dans sa couleur."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "Une lumière douce dans la couleur de la ligne la parcourt quand elle apparaît ou s'incrémente."
L["A soft light round the frame in the debuff's type color."] = "Une lumière douce autour du cadre dans la couleur du type d'affaiblissement."
L["A soft light round the tile in the debuff's type color."] = "Une lumière douce autour de la tuile dans la couleur du type d'affaiblissement."
L["A soft shadow round each button."] = "Une ombre douce autour de chaque bouton."
L["A soft sound when your name or one of your words shows up."] = "Un son discret quand votre nom ou l'un de vos mots apparaît."
L["A soft, minimal interface."] = "Une interface douce et minimaliste."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "Un carillon doux et chaleureux quand une quête suivie est prête à être rendue."
L["A space"] = "Une espace"
L["A spell that just lit up, like Overpower or Execute."] = "Un sort qui vient de s'allumer, comme Fulgurance ou Exécution."
L["A spell with charges: the bar is cut into one piece per charge."] = "Un sort à charges : la barre est découpée en un segment par charge."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "L'icône d'un sort ressort et s'illumine une fois quand il sort d'un vrai temps de recharge (jamais pour le temps de recharge global). Nécessite les Effets de mouvement (Général > Apparence)."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "L'icône d'un sort devient grise pendant son temps de recharge. Le temps de recharge global ne compte pas."
L["A square minimap in the panel. Scroll to zoom."] = "Une minicarte carrée dans le panneau. Faites défiler pour zoomer."
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "Un étourdissement, une peur, une métamorphose et autres, sous forme d'une icône plus grande à côté de l'extrémité de la barre."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Un symbole sur la carte du monde à chaque quai de bateau et tour de zeppelin. Survolez-le pour voir sa destination."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Un symbole sur la carte du monde à chaque entrée de donjon et de raid. Survolez-le pour voir le nom."
L["A thin bar under the name."] = "Une fine barre sous le nom."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "Une fine ligne en travers des barres là où votre menace vous ferait prendre l'aggro : 110% de celle du tank en mêlée, 130% à distance. Non affichée sur un boss, dont le jeu masque les chiffres."
L["A thin line in your accent color along the top of the chat."] = "Une fine ligne de votre couleur d'accent le long du haut de la discussion."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "Une fine bande de mana en bas de la barre de ressource quand une forme masque votre mana."
L["A thin mana, rage or energy bar at the foot of each tile."] = "Une fine barre de mana, de rage ou d'énergie au pied de chaque tuile."
L["A thin outline on chat text."] = "Un fin contour sur le texte de la discussion."
L["A thin power bar under each pet's health."] = "Une fine barre de ressource sous la vie de chaque familier."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "Une fine bande sous la minicarte : or, équipement, place dans les sacs, amis en ligne. Survolez un élément pour les détails, cliquez pour ouvrir sa fenêtre."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "Un contour plus fin laisse plus de place à la couleur dans chaque pastille. Réglez sur 0 pour aucun."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "L'infobulle d'un élément du monde (une créature, un joueur, une boîte aux lettres) s'estompe lentement quand la souris s'en éloigne, comme dans le jeu. Désactivé, elle disparaît immédiatement."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "Une traînée de petits losanges de vos pieds jusqu'au marqueur, dérivant vers lui. Comme le marqueur, elle s'estompe une fois que vous êtes dans la zone de la quête sur la carte."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "Une visite de deux minutes de tout ce que fait DaylightUI, en faisant vos choix au fur et à mesure. Rien n'est enregistré avant la fin."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "Une ligne de lumière chaude s'étend en haut de l'écran, votre nouveau niveau défile et vos gains apparaissent en fondu en dessous, à la place de la bannière du jeu. Suit les Effets de mouvement (Général > Apparence)."
L["A warning when your health or mana drops low."] = "Un avertissement quand votre vie ou votre mana devient basse."
L["A word when a fight starts and ends."] = "Un mot quand un combat commence et se termine."
L["AFK"] = "ABS"
L["AVOIDABLE"] = "ÉVITABLE"
L["AWAY"] = "ABSENT"
L["Abandon"] = "Abandonner"
L["Abandon \"%s\"?"] = "Abandonner « %s » ?"
L["Abandon?"] = "Abandonner ?"
L["About 1 in %d of your attacks hits for double damage."] = "Environ 1 de vos attaques sur %d inflige le double de dégâts."
L["About 1 in %d of your shots hits for double damage."] = "Environ 1 de vos tirs sur %d inflige le double de dégâts."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "Environ 1 de vos sorts sur %d inflige un coup critique, soit 50% de plus."
L["Above"] = "Au-dessus"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "Au-dessus ou en dessous du cadre, la barre est aussi large que le cadre. Désactivé : la Largeur ci-dessous."
L["Above or below the frame: moves the bar sideways from the middle."] = "Au-dessus ou en dessous du cadre : décale la barre latéralement par rapport au centre."
L["Above or below the frame: moves the bar up or down."] = "Au-dessus ou en dessous du cadre : déplace la barre vers le haut ou le bas."
L["Above the frame"] = "Au-dessus du cadre"
L["Above the health bar"] = "Au-dessus de la barre de vie"
L["Above the name tab by default, running inward. Yours come first."] = "Au-dessus de l'onglet du nom par défaut, vers l'intérieur. Les vôtres en premier."
L["Above your debuffs, from the right."] = "Au-dessus de vos affaiblissements, depuis la droite."
L["Absorb shields"] = "Boucliers d'absorption"
L["Absorbs"] = "Absorptions"
L["Accent"] = "Accent"
L["Accent color"] = "Couleur d'accent"
L["Accent follows Appearance, including the Daylight gradient."] = "Accent suit l'Apparence, y compris le dégradé Daylight."
L["Accent follows the accent color on the Appearance page. Class uses your class's gradient (set on the Gradients page). Reputation keeps its standing's colors."] = "Accent suit la couleur d'accent de la page Apparence. Classe utilise le dégradé de votre classe (réglé sur la page Dégradés). Réputation garde les couleurs de son rang."
L["Accent follows the accent you picked on the General page, gradient and all."] = "Accent suit l'accent choisi sur la page Général, dégradé compris."
L["Accent follows your accent color (General > Appearance), or pick your own."] = "Accent suit votre couleur d'accent (Général > Apparence), ou choisissez la vôtre."
L["Accent line on top"] = "Ligne d'accent en haut"
L["Accept"] = "Accepter"
L["Accept key"] = "Touche d'acceptation"
L["Accept quests automatically"] = "Accepter les quêtes automatiquement"
L["Account"] = "Compte"
L["Achievement announcements."] = "Annonces de hauts faits."
L["Achievement color"] = "Couleur des hauts faits"
L["Achievements"] = "Hauts faits"
L["Across"] = "En travers"
L["Across the bar"] = "En travers de la barre"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "En travers de la barre le garde à l'intérieur. Toute autre position le place à cet endroit, sur ou autour du cadre, pour laisser de la place à un nom long. Vous pouvez aussi le faire glisser en mode Conception."
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "En travers de la barre conserve l'alignement ci-dessous. À côté de la tuile nécessite de l'espace entre les tuiles."
L["Across, you shown, by role, icons in corners"] = "En ligne, vous affiché, par rôle, icônes dans les coins"
L["Action Bar 1"] = "Barre d'actions 1"
L["Action Bar 2"] = "Barre d'actions 2"
L["Action Bar 3"] = "Barre d'actions 3"
L["Action Bar 4"] = "Barre d'actions 4"
L["Action Bar 5"] = "Barre d'actions 5"
L["Action Bar 6"] = "Barre d'actions 6"
L["Action Bar 7"] = "Barre d'actions 7"
L["Action Bar 8"] = "Barre d'actions 8"
L["Action Bars"] = "Barres d'actions"
L["Action bars"] = "Barres d'actions"
L["Activate"] = "Activer"
L["Activate this set first."] = "Activez d'abord cet ensemble."
L["Active spell"] = "Sort actif"
L["Active spell color"] = "Couleur du sort actif"
L["Active spell opacity"] = "Opacité du sort actif"
L["Add"] = "Ajouter"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "Ajouter un ami : un BattleTag (Nom#1234) ou le nom d'un personnage."
L["Add a group"] = "Ajouter un groupe"
L["Add friend"] = "Ajouter un ami"
L["Add to favorites"] = "Ajouter aux favoris"
L["AddOns"] = "AddOns"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "Ajouté avec Ajouter un élément en mode Conception. Faites-le glisser sur l'aperçu pour le déplacer. Jusqu'à trois parties sur une ligne, chacune dans sa propre couleur."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "Ajouté avec Ajouter un élément en mode Conception : une rangée d'auras supplémentaire, avec son propre filtre."
L["Addon button drawer"] = "Tiroir des boutons d'addons"
L["Addon options (Ace3)"] = "Options des addons (Ace3)"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "Les boutons de minicarte des addons et le menu des addons du jeu sont regroupés dans un tiroir. Le bouton dans le coin inférieur droit de la carte l'ouvre."
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "Ajoute une bande chaude à l'intérieur du contour noir, éclairée sur le haut. Désactivé, la bordure est une simple ligne sombre."
L["Adds about %.0f damage per second to your melee attacks."] = "Ajoute environ %.0f dégâts par seconde à vos attaques en mêlée."
L["Adds about %.0f damage per second to your shots."] = "Ajoute environ %.0f dégâts par seconde à vos tirs."
L["Adds up to %.0f to your heals."] = "Ajoute jusqu'à %.0f à vos soins."
L["Adds up to %.0f to your spells' damage."] = "Ajoute jusqu'à %.0f aux dégâts de vos sorts."
L["Adventure"] = "Aventure"
L["Affliction"] = "Affliction"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "Après un /reload, les derniers messages de chaque onglet de discussion réapparaissent, au-dessus d'une ligne grise."
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "Après une connexion ou un /reload, l'interface démarre invisible puis apparaît en glissant. Tout élément réglé pour s'estomper finit estompé."
L["After a player's guild name."] = "Après le nom de guilde d'un joueur."
L["After combat"] = "Après le combat"
L["After the fight"] = "Après le combat"
L["Aggro"] = "Aggro"
L["Aggro color"] = "Couleur d'aggro"
L["Aggro colors"] = "Couleurs d'aggro"
L["Agility"] = "Agilité"
L["Ah, a fresh face. Goldshire isn't what it was, with kobolds in every mine. Still, a man has to keep his shop."] = "Ah, un nouveau visage. Comté-de-l'Or n'est plus ce qu'il était, avec des kobolds dans chaque mine. Mais il faut bien tenir boutique."
L["Alfa Slab One"] = "Alfa Slab One"
L["Alignment"] = "Alignement"
L["All"] = "Tout"
L["All %d spells snapped together"] = "Les %d sorts sont accolés"
L["All activities"] = "Toutes les activités"
L["Show all"] = "Tout afficher"
L["%d activities"] = "%d activités"
L["All addons: %.3f ms"] = "Tous les addons : %.3f ms"
L["All bars"] = "Toutes les barres"
L["All characters"] = "Tous les personnages"
L["All debuffs"] = "Tous les affaiblissements"
L["All donators"] = "Tous les donateurs"
L["All four extra aura groups are in use: remove one first."] = "Les quatre groupes d'auras supplémentaires sont utilisés : supprimez-en un d'abord."
L["All four extra texts are in use: remove one first."] = "Les quatre textes supplémentaires sont utilisés : supprimez-en un d'abord."
L["All frames are back in their default places."] = "Tous les cadres sont revenus à leur place par défaut."
L["All points"] = "Tous les points"
L["All quests"] = "Toutes les quêtes"
L["All set"] = "Tout est prêt"
L["All slots"] = "Tous les emplacements"
L["All time"] = "Depuis toujours"
L["All tracked quests"] = "Toutes les quêtes suivies"
L["All your bags in one window, profession bag and keyring included. It opens the same way the game's bags do."] = "Tous vos sacs dans une seule fenêtre, sac de métier et trousseau de clés compris. Elle s'ouvre de la même façon que les sacs du jeu."
L["Almost ready at"] = "Presque prêt à"
L["Almost ready color"] = "Couleur presque prêt"
L["Almost there"] = "Presque arrivé"
L["Also destroys %s."] = "Détruit aussi %s."
L["Alt"] = "Alt"
L["Alt-click on a quest"] = "Alt-clic sur une quête"
L["Alt-click: %s"] = "Alt-clic : %s"
L["Always"] = "Toujours"
L["Always (floating)"] = "Toujours (flottant)"
L["Always a skill point"] = "Toujours un point de compétence"
L["Ammo"] = "Munitions"
L["An Item Level line on weapon and armor tooltips, in soft gold."] = "Une ligne Niveau d'objet dans les infobulles d'armes et d'armures, en doré doux."
L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "Une flèche à l'écran qui pointe vers le monstre ou l'objet le plus proche encore nécessaire pour la quête choisie, puis vers le donneur de quête une fois celle-ci prête, avec la distance en dessous. Rien n'est ajouté sur la carte. Nécessite l'addon QuestieDB."
L["An item link shows your equipped item beside it, as the game's own compare setting says. Off, only while Shift is held."] = "Un lien d'objet affiche à côté l'objet que vous portez, selon le réglage de comparaison du jeu. Désactivé, seulement en maintenant Maj."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "Les lignes vertes « Équipé : » d'un objet en quelques mots (« Augmente vos chances de toucher de 1% » devient « +1% Toucher »), et chaque caractéristique dans sa propre couleur : chaque école, toucher, critique, puissance des sorts, soins, caractéristiques de base. Les déclenchements et effets d'utilisation restent inchangés."
L["An objective you've finished."] = "Un objectif que vous avez accompli."
L["An outline around its bar, a soft glow around it, or nothing."] = "Un contour autour de sa barre, une lueur douce autour, ou rien."
L["And %d more"] = "Et %d de plus"
L["And %d more: keep typing to narrow it down."] = "Et %d de plus : continuez à taper pour affiner."
