L["Another layout to copy: your other talent set, your other characters', or a layout from before layouts were per character."] = "Une autre disposition à copier : votre autre jeu de talents, celles de vos autres personnages, ou une disposition d'avant que les dispositions soient propres à chaque personnage."
L["Another player's gear and talents in one window, in DaylightUI style."] = "L'équipement et les talents d'un autre joueur dans une seule fenêtre, au style DaylightUI."
