L["Class and profession trainers open in the NPC window too, with what you can learn now and what's coming up. Pick a spell, then press Train or Train all: a click or a key alone never spends gold. Turn it off to use the game's trainer window."] = "Les maîtres de classe et de métier s'ouvrent aussi dans la fenêtre des PNJ, avec ce que vous pouvez apprendre maintenant et ce qui arrive ensuite. Choisissez un sort, puis appuyez sur Apprendre ou Tout apprendre : un simple clic ou une touche seule ne dépense jamais d'or. Désactivez pour utiliser la fenêtre de maître du jeu."
L["Class and reaction"] = "Classe et réaction"
L["Class and reaction: players by class color, others by friendly, neutral or hostile. Dark: a near-black bar with the missing health in the class or reaction color."] = "Classe et réaction : les joueurs selon la couleur de leur classe, les autres selon qu'ils sont amicaux, neutres ou hostiles. Sombre : une barre presque noire avec la vie manquante dans la couleur de classe ou de réaction."
