L["Class gradient uses your class's pair from the Gradients page."] = "Le dégradé de classe utilise la paire de votre classe définie sur la page Dégradés."
L["Class gradient: the unit's class colors (an NPC's are by how friendly it is), and the red aggro ring is shaded to match. Accent color: your accent on every frame. Daylight gradient: the logo's colors on every frame. Light: a gray ring. Dark: the same dark border as the frame."] = "Dégradé de classe : les couleurs de classe de l'unité (celles d'un PNJ dépendent de son attitude), et l'anneau d'aggro rouge est nuancé en conséquence. Couleur d'accent : votre accent sur chaque cadre. Dégradé Daylight : les couleurs du logo sur chaque cadre. Clair : un anneau gris. Sombre : la même bordure sombre que le cadre."
