L["Custom zone name color"] = "Couleur personnalisée du nom de zone"
L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "Coupe les deux extrémités de chaque ligne en biais. Désactivé, les extrémités sont droites."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "Coupe l'extrémité droite de chaque tuile en biais, comme votre propre cadre ; les barres suivent."
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "Coupe une extrémité de chaque barre de familier en biais. Désactivé, les extrémités sont droites."
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "Coupe l'extrémité de la barre en biais. Désactivé, l'extrémité est droite."
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Coupe l'extrémité de la barre de sorts de votre focalisation en biais. Désactivé, son extrémité est droite. Pas quand elle est placée dans le cadre."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Coupe l'extrémité de la barre de sorts de votre cible en biais. Désactivé, son extrémité est droite. Pas quand elle est placée dans le cadre."
L["Cuts the frame's inner end at an angle; the bars follow it."] = "Coupe l'extrémité intérieure du cadre en biais ; les barres suivent."
L["Cuts the left end at an angle; the bars follow it."] = "Coupe l'extrémité gauche en biais ; les barres suivent."
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "Coupe l'extrémité droite en biais ; les barres et une barre de sorts attachée suivent."
L["Cuts the right end at an angle; the bars follow it."] = "Coupe l'extrémité droite en biais ; les barres suivent."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "Les cinématiques et vidéos d'introduction se terminent immédiatement. Maintenez Maj au lancement de l'une d'elles pour la regarder."
L["DAMAGE"] = "DÉGÂTS"
L["DEAD"] = "MORT"
L["DEATHS"] = "MORTS"
L["Dispel icon left / right"] = "Icône de dissipation gauche / droite"
L["Dispel icon up / down"] = "Icône de dissipation haut / bas"
L["DISPELS"] = "DISSIPATIONS"
L["DND"] = "DND"
L["DPS / Tank"] = "DPS / Tank"
L["DPS / Tank (as it comes)"] = "DPS / Tank (tel quel)"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank rendu calme pour les quêtes : vos barres d'actions et votre propre cadre s'estompent un moment après un combat (ils reviennent sous la souris, en combat ou quand vous êtes blessé), le compteur de dégâts démarre replié (un clic sur l'onglet du panneau le fait apparaître), la minicarte est un peu plus petite et la barre d'expérience affiche son pourcentage. Rien ne s'estompe en donjon, raid, champ de bataille ou arène (Général > Apparence, Fondu uniquement en monde ouvert). Choisissez-le ci-dessus pour l'utiliser. Si le profil actuel a des barres d'actions déplacées, propose de les reprendre."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank avec votre groupe et votre raid en tuiles carrées sous vous (vous compris, avec la vie manquante, les dissipations bien visibles), et votre cadre et celui de votre cible un peu surélevés. Tout ce qu'il règle se trouve sur les pages Groupe et Raid ; déplacez n'importe quel élément en mode déverrouillage. Choisissez-le ci-dessus pour l'utiliser. Si le profil actuel a des barres d'actions déplacées, propose de les reprendre."
L["Damage"] = "Dégâts"
L["Damage / Tank"] = "Dégâts / Tank"
L["Damage Meter"] = "Compteur de dégâts"
L["Damage dealers get a role icon too. When off, only tanks and healers get one."] = "Les DPS ont aussi une icône de rôle. Désactivé, seuls les tanks et les soigneurs en ont une."
L["Damage done"] = "Dégâts infligés"
L["Damage meter"] = "Compteur de dégâts"
L["Damage meter position"] = "Position du compteur de dégâts"
L["Damage numbers"] = "Chiffres de dégâts"
L["Damage shields, as a pale stretch after any incoming heals."] = "Boucliers absorbant les dégâts, sous forme d'une portion pâle après les soins entrants."
L["Damage taken"] = "Dégâts subis"
L["Damage you deal"] = "Dégâts que vous infligez"
L["Dark"] = "Sombre"
L["Dark (missing health colored)"] = "Sombre (vie manquante colorée)"
L["Dark end, then light end. The bar next to them is a preview."] = "Extrémité sombre, puis extrémité claire. La barre à côté sert d'aperçu."
L["Dark tooltips with class colors, item quality borders and a health bar."] = "Infobulles sombres avec couleurs de classe, bordures selon la qualité des objets et une barre de vie."
