L["Data text slot 2"] = "Emplacement de texte d'info 2"
L["Data text slot 3"] = "Emplacement de texte d'info 3"
L["Data text slot 4"] = "Emplacement de texte d'info 4"
L["Data text slot 5"] = "Emplacement de texte d'info 5"
