L["Daylight"] = "Daylight"
L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI n'a pas pu habiller %s %s : il est laissé tel quel."
L["Daylight UI's chat box in the bottom-left corner, with whispers as conversations beside it. Chat style: Classic keeps the game's own chat windows instead."] = "La zone de discussion de Daylight UI dans le coin inférieur gauche, avec les chuchotements en conversations à côté. Le style de discussion Classique conserve à la place les fenêtres de discussion du jeu."
L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "Le journal, le marqueur et la flèche de Daylight UI restent dans tous les cas. Vous pourrez le modifier plus tard dans la page d'options Quêtes."
L["Daylight gradient"] = "Dégradé Daylight"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight est la bande chaude dans un contour sombre, Plat un simple contour. Avec Aucun, l'icône remplit tout le bouton."
L["Daylight look"] = "Apparence Daylight"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message."] = "Daylight : la zone de discussion propre à Daylight UI, avec ses propres onglets. Classique : les fenêtres et onglets de discussion du jeu avec l'apparence Daylight. Le changement est instantané, et les deux conservent tous les messages."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight : le cadre avec son nom dans un onglet au-dessus et la barre de ressource à l'intérieur. Ruban : une barre fine avec le nom et la vie flottant au-dessus et la ressource en fine ligne en dessous. Par défaut utilise le style défini pour tous les cadres (Extras > Style des cadres). Chaque style conserve ses propres hauteurs."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight : le cadre avec son nom dans un onglet au-dessus et la barre de ressource à l'intérieur. Ruban : une barre fine avec le nom et la vie flottant au-dessus et la ressource en fine ligne en dessous. Chaque cadre peut choisir le sien sur sa page."
L["DaylightMogul's mailbox is in use."] = "La boîte aux lettres de DaylightMogul est utilisée."
L["DaylightMogul's profession window is in use."] = "La fenêtre de métier de DaylightMogul est utilisée."
L["DaylightMogul's vendor window is in use."] = "La fenêtre de marchand de DaylightMogul est utilisée."
L["DaylightUI"] = "DaylightUI"
L["DaylightUI (General)"] = "DaylightUI (Général)"
L["DaylightUI Discord"] = "Discord DaylightUI"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "DaylightUI a un nouveau guide de configuration. Faites la visite pour découvrir tout ce qu'il peut faire, ou gardez votre configuration actuelle."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "DaylightUI est configuré sur ce personnage. Recharger pour l'appliquer ?"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "Apparence DaylightUI pour les bulles de dialogue (dire, crier, groupe). Les instances gardent les bulles du jeu, car les addons ne peuvent pas les y modifier."
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI a déplacé le suivi de quêtes pour l'adapter au panneau. Recharger pour l'appliquer ?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI a mis en place la disposition du Mode Édition de ce profil. Recharger pour l'utiliser ?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI remplace vos cadres, barres, sacs, discussion et plus encore par une apparence douce et minimaliste. Configurons ce personnage."
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI a enregistré la position de la fenêtre de butin. Recharger pour l'appliquer ?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "DaylightUI a enregistré la position du suivi de quêtes. Recharger pour l'appliquer ?"
