L["Drag a piece to move it. Click it for its settings; the arrow keys then nudge it."] = "Faites glisser un élément pour le déplacer. Cliquez dessus pour ses réglages ; les flèches le décalent ensuite."
L["Drag a tab to move it. Right-click: what it shows, rename, remove"] = "Faites glisser un onglet pour le déplacer. Clic droit : ce qu'il affiche, renommer, retirer"
L["Drag it to an action bar."] = "Faites-le glisser sur une barre d'actions."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "Faites glisser les éléments de l'aperçu pour les déplacer : chacun reste là où vous le lâchez, ou s'accroche à un point juste à côté. Cliquez sur un élément, et les flèches le décalent (Maj pour de plus grands pas). Chaque déplacement modifie les mêmes réglages que les cartes ci-dessous."
L["Drag to move it, or click for its settings."] = "Faites glisser pour le déplacer, ou cliquez pour ses réglages."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "Faites glisser pour déplacer. Déposez-le à côté d'un autre élément pour l'y accrocher, éloignez-le pour le libérer. Supprimer le retire."
L["Dragon around the portrait"] = "Dragon autour du portrait"
L["Dragon color"] = "Couleur du dragon"
L["Drop an item here"] = "Déposez un objet ici"
L["Druid"] = "Druide"
L["Druid mana in forms"] = "Mana du druide en forme"
