L["Dungeon Journal"] = "Codex des donjons"
L["Dungeon and raid entrances"] = "Entrées de donjons et de raids"
L["Dungeon tag color"] = "Couleur de l'étiquette de donjon"
L["Dungeons, raids and battlegrounds"] = "Donjons, raids et champs de bataille"
L["Durability"] = "Durabilité"
L["Durability %s"] = "Durabilité %s"
L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "Pendant un appel, une coche, une croix ou un point d'interrogation sur chaque membre : prêt, pas prêt ou pas encore de réponse. Ils restent quelques secondes après la fin de l'appel."
L["ENEMY TAKEN"] = "SUBIS (ENNEMIS)"
L["Each bar in its player's class color, or all in one color."] = "Chaque barre dans la couleur de classe de son joueur, ou toutes d'une seule couleur."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "La main de chaque barre (ou l'attaque en attente) et le temps avant le prochain coup, inscrits sur la barre."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "La forme de chaque barre et quand elle s'affiche. Les modifications s'appliquent immédiatement. Déplacez les barres en mode déverrouillage."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "La taille, la forme de chaque barre et quand elle s'affiche. Choisissez la barre avec « Réglages pour »."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "Chaque personnage utilise un profil (un par jeu de talents, avec la double spécialisation). Tout ce qui se trouve sur chaque page modifie le profil utilisé."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "Les sacs de chaque personnage sont enregistrés à la déconnexion, et sa banque à chaque visite chez un banquier. Consultez-les partout avec le bouton coffre de vos sacs, ou /dui bank. Désactivé, le bouton disparaît et plus rien n'est enregistré."
L["Each combo point you build on your target."] = "Chaque point de combo que vous accumulez sur votre cible."
L["Each icon darkens like a clock as its time runs out."] = "Chaque icône s'assombrit comme une horloge à mesure que son temps s'écoule."
L["Each icon's width and height."] = "Largeur et hauteur de chaque icône."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "Le nom et le niveau d'objet de chaque objet à côté de son icône. Désactivé, seules les icônes s'affichent, avec le niveau d'objet dans chaque coin et plus de place pour le modèle."
L["Each its own"] = "Chacun le sien"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "Chaque coup de la main droite inflige %.0f à %.0f avant armure."
L["Each member's health written on their tile."] = "La vie de chaque membre inscrite sur sa tuile."
L["Each member's name on their tile."] = "Le nom de chaque membre sur sa tuile."
L["Each new message fades in instead of appearing at once. Never in a fight."] = "Chaque nouveau message apparaît en fondu au lieu de s'afficher d'un coup. Jamais en combat."
L["Each objective line under a quest."] = "Chaque ligne d'objectif sous une quête."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "Chaque personne qui vous chuchote obtient un onglet à côté des autres, et le chuchotement s'affiche aussi dans votre onglet principal. Désactivé, les chuchotements ne s'affichent que dans l'onglet principal."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "Chaque segment s'incline comme les extrémités biseautées des cadres. Désactivé, leurs extrémités sont droites."
L["Each pip's end cut at an angle, like the health bar's."] = "L'extrémité de chaque segment coupée en biais, comme celle de la barre de vie."
L["Each quest's level in front of its title, like [15]."] = "Le niveau de chaque quête devant son titre, comme [15]."
L["Each quest's title in the tracker."] = "Le titre de chaque quête dans le suivi."
L["Each shot hits for %.0f to %.0f before armor."] = "Chaque tir inflige %.0f à %.0f avant armure."
L["Each square darkens like a clock as your spell runs out."] = "Chaque carré s'assombrit comme une horloge à mesure que votre sort s'écoule."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "Chaque jeu de talents a sa propre disposition. « Modifier la disposition » et « Copier depuis » agissent sur celle-ci."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "Chaque texte se met à jour dès qu'il change. Survolez pour les détails : l'or sur chaque personnage, chaque pièce d'équipement, chaque sac, qui est en ligne."
L["Each threat bar in its player's class color, or all in one color."] = "Chaque barre de menace dans la couleur de classe de son joueur, ou toutes d'une seule couleur."
L["Early start"] = "Démarrage anticipé"
L["Earned"] = "Gagné"
L["Earned this session"] = "Gagné cette session"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "Atténue les couleurs de classe, de réaction et de ressource vers le gris pour un rendu plus doux."
L["Edit"] = "Modifier"
