L["Edit Mode is open; close it first"] = "Le Mode Édition est ouvert ; fermez-le d'abord"
L["Edit layout"] = "Modifier la disposition"
L["Edit listing"] = "Modifier l'annonce"
L["Edit on screen"] = "Modifier à l'écran"
L["Eight candles, and hardly a dent in them! Here, pick something for your trouble."] = "Huit bougies, et à peine entamées ! Tenez, choisissez quelque chose pour votre peine."
