L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "Les familiers et totems ennemis ont leur propre apparence, les totems dans la couleur de leur élément. En champ de bataille, ils sont tous rouges : le jeu masque de quel totem il s'agit. Désactivé, le réglage du jeu pour leurs barres d'info est aussi désactivé."
L["Enemy plates: the health bar, the name under it, casts, your debuffs and crowd control. Friendly plates are simpler."] = "Barres d'info ennemies : la barre de vie, le nom en dessous, les incantations, vos affaiblissements et le contrôle de foule. Les barres d'info alliées sont plus simples."
