L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "Entrée répond oui quand quelqu'un vous demande quelque chose : une invitation de groupe, une quête partagée, une invocation, une résurrection. Jamais pour ce qui lie, lance un jet de dés ou coûte quelque chose, et jamais en combat. Choisir une auberge comme foyer accepte aussi votre Touche d'acceptation."
