L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "Tous les affaiblissements sur vous, au-dessus de votre cadre. Désactivé par défaut : vos barres d'améliorations les affichent aussi."
L["Every empty slot"] = "Chaque emplacement vide"
L["Every font"] = "Toutes les polices"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "La barre de chaque main dans la couleur de votre classe, ou le dégradé de votre classe avec un remplissage bicolore. Une attaque en file garde sa propre couleur. Pas avec le dégradé Daylight."
L["Every header in this one color."] = "Tous les en-têtes dans cette seule couleur."
L["Every health bar's color when Health bar color is One color."] = "Couleur de toutes les barres de vie quand « Couleur de la barre de vie » est sur « Une couleur »."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Chaque objet que vous avez glissé sur un groupe, ou déplacé avec Alt-clic droit, retourne dans son propre groupe."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "Toutes les lignes des infobulles. « Général » utilise la police de Général > Apparence."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "Toutes les lignes restent jusqu'à expiration de la plus récente, puis disparaissent ensemble. Désactivé, chaque ligne part d'elle-même."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "Une ligne sur deux sur une bande discrète, dans les statistiques et les longues listes, pour suivre les lignes plus facilement."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "Chaque partie de DaylightUI et ce qu'elle fait. Désactivez celles dont vous ne voulez pas ; cela s'applique au rechargement."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "Le fondu de chaque partie au même endroit. Chacun est le même réglage que sur la page de cette partie."
L["Every power bar's color when Power bar color is One color."] = "Couleur de toutes les barres de ressource quand « Couleur de la barre de ressource » est sur « Une couleur »."
L["Every quest in your log"] = "Toutes les quêtes de votre journal"
L["Every quest title's color while Quest title color is set to One color."] = "Couleur de tous les titres de quête quand « Couleur du titre de quête » est sur « Une couleur »."
L["Every reward earned."] = "Chaque récompense obtenue."
L["Every setting for this piece"] = "Tous les réglages de cet élément"
L["Every text in the loot feed. General uses the font on General > Appearance."] = "Tous les textes du flux de butin. « Général » utilise la police de Général > Apparence."
