L["Every tracked quest, only the zone you're in, or every quest in your log without tracking them. The controls over the list switch the first two."] = "Toutes les quêtes suivies, seulement la zone où vous êtes, ou toutes les quêtes de votre journal sans les suivre. Les contrôles au-dessus de la liste basculent entre les deux premiers."
