L["Fade out of combat"] = "Estomper hors combat"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "Estomper hors combat : s'estompe un moment après un combat et revient en combat. Estomper en combat : s'estompe un moment après le début d'un combat et revient ensuite. Estomper jusqu'au survol : reste estompé jusqu'à ce que la souris passe dessus. Seulement lors d'un changement : disparaît hors combat, revient en combat, et revient un instant quand quelque chose change (amélioration gagnée ou perdue, votre vie, progression de quête, PX)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "Estomper hors combat : s'estompe un moment après un combat et revient en combat. Estomper en combat : s'estompe un moment après le début d'un combat et revient ensuite. Estomper jusqu'au survol : reste estompé jusqu'à ce que la souris passe dessus. Seulement lors d'un changement : disparaît hors combat, revient en combat, et revient un instant quand quelque chose change (amélioration gagnée ou perdue, votre vie, progression de quête, PX). Masqué (en combat, hors combat ou toujours) : disparaît, et ses boutons ne peuvent pas être cliqués."
L["Fade the UI while talking"] = "Estomper l'interface pendant le dialogue"
