L["Gives the name tab the border, corners and shadow below. When off, it matches the frame."] = "Donne à l'onglet du nom la bordure, les coins et l'ombre ci-dessous. Désactivé, il suit le cadre."
L["Gives this frame the border, corners and shadow below. When off, it follows General > Appearance."] = "Donne à ce cadre la bordure, les coins et l'ombre ci-dessous. Désactivé, il suit Général > Apparence."
