L["Glow on proc"] = "Lueur au déclenchement"
L["Glow when usable"] = "Lueur quand utilisable"
L["Glows while the buff is down, to remind you to cast it, wherever it keeps its spot (Keep its spot, above)."] = "Brille tant que l'amélioration est absente, pour vous rappeler de la lancer, là où elle garde sa place (« Garder sa place », ci-dessus)."
L["Glows while the buff is down, to remind you to cast it."] = "Brille tant que l'amélioration est absente, pour vous rappeler de la lancer."
L["Glows while the spell is off cooldown."] = "Brille tant que le sort n'est pas en recharge."
L["Glows while you can cast it and it's off cooldown: Revenge after a block, dodge or parry, Overpower after a dodge, Execute on a low target."] = "Brille tant que vous pouvez le lancer et qu'il n'est pas en recharge : Vengeance après un blocage, une esquive ou une parade, Fulgurance après une esquive, Exécution sur une cible affaiblie."
