L["Hide gold-seller adverts"] = "Masquer les publicités de vendeurs d'or"
L["Hide keeps its gap: the other spells don't move."] = "« Masquer » garde son emplacement : les autres sorts ne bougent pas."
L["Hide lower ranks"] = "Masquer les rangs inférieurs"
L["Hide repeated messages"] = "Masquer les messages répétés"
L["Hide shows the spell only while it's on cooldown. It keeps its gap: the other spells don't move."] = "Masquer n'affiche le sort que pendant son temps de recharge. Sa place reste vide : les autres sorts ne bougent pas."
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "« Masquer » n'affiche le sort que pendant sa recharge. « Seulement quand utilisable » l'affiche dès que vous pouvez le lancer : Riposte après une parade, Fulgurance après une esquive, Exécution sur une cible affaiblie. Les deux gardent l'emplacement : les autres sorts ne bougent pas."
L["Hide while mounted"] = "Masquer sur une monture"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "Masque les groupes de raid supérieurs, par ex. 4 pour un raid de 20 joueurs."
L["Hides the number while a minute or more is left, so long buffs stay quiet."] = "Masque le nombre tant qu'il reste une minute ou plus, pour que les longues améliorations restent discrètes."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "Masque le texte rouge et la réplique vocale quand vous appuyez trop tôt sur un bouton : pas assez de rage, de mana ou d'énergie, pas encore prêt, hors de portée, pas de cible. Les messages utiles restent affichés : sacs pleins, interrompu, ligne de vue, messages de quête."
L["Hiding"] = "Masquage"
L["Highlight"] = "Surbrillance"
L["Highlight color"] = "Couleur de surbrillance"
L["Highlights a spell that is active (an aura, auto attack, a stance) or being cast."] = "Met en surbrillance un sort actif (une aura, l'attaque automatique, une posture) ou en cours d'incantation."
L["History"] = "Historique"
L["Hold: move to another group"] = "Maintenir : déplacer vers un autre groupe"
L["Holy"] = "Sacré"
L["Holy Light"] = "Lumière sacrée"
L["Home"] = "Accueil"
L["Honor"] = "Honneur"
L["Honor gains"] = "Gains d'honneur"
L["Honor you earn in PvP."] = "Honneur gagné en JcJ."
L["Honored"] = "Honoré"
L["Hooked above %s"] = "Accroché au-dessus de %s"
L["Hooked below %s"] = "Accroché sous %s"
L["Hooked left of %s"] = "Accroché à gauche de %s"
L["Hooked right of %s"] = "Accroché à droite de %s"
L["Horizontal (light at the full end)"] = "Horizontal (clair du côté plein)"
L["Hostile"] = "Hostile"
L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "Survolez un bouton et appuyez sur une touche pour l'assigner, ou sur Échap pour l'effacer. Cliquez sur « OK » quand vous avez terminé. Hors combat uniquement."
L["Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Survolez un réglage pour voir ce qu'il fait ; la flèche à côté d'un réglage modifié le rétablit."
L["Hover delay (seconds)"] = "Délai de survol (secondes)"
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "Survolez-le pour afficher les boutons : le combat (global, actuel, et combats précédents par nom), le mode et la réinitialisation."
L["Hovering a Questie icon on the map or minimap, or a quest in the quest log, makes that quest's icons a little bigger and fades the other quests' icons."] = "Survoler une icône Questie sur la carte ou la minicarte, ou une quête dans le journal des quêtes, agrandit un peu les icônes de cette quête et estompe celles des autres quêtes."
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "Survoler une quête du journal des quêtes affiche son infobulle à côté du journal, comme le journal du jeu. Désactivé, elle s'affiche à la souris."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "Survoler un lien d'objet, de sort ou de quête dans la discussion affiche son infobulle, juste au-dessus de la discussion."
L["Hovering an item, spell or quest link in chat shows its tooltip. Off, clicking a link still opens it."] = "Survoler un lien d'objet, de sort ou de quête dans la discussion affiche son infobulle. Désactivé, un clic sur le lien l'ouvre toujours."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "Taille de l'apparition d'un critique sur vous. Il commence à la moitié de cette valeur puis revient. Celle du jeu est de 60."
L["How big each buff icon is."] = "Taille de chaque icône d'amélioration."
L["How big each debuff icon is."] = "Taille de chaque icône d'affaiblissement."
L["How big each icon is."] = "Taille de chaque icône."
L["How big each item slot is in the Bank and alts window."] = "Taille de chaque emplacement d'objet dans la fenêtre Banque et personnages secondaires."
L["How big each item slot is in the bag."] = "Taille de chaque emplacement d'objet dans le sac."
L["How big each item slot is in the bank."] = "Taille de chaque emplacement d'objet dans la banque."
L["How big every square is."] = "Taille de chaque carré."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "Sa taille, en pourcentage de sa taille normale. C'est le réglage de taille du Mode Édition, conservé dans votre disposition du Mode Édition."
L["How big the PvP flag is."] = "Taille de l'indicateur JcJ."
L["How big the arrow is on your screen, yards text included."] = "Taille de la flèche à l'écran, texte des mètres compris."
L["How big the clock is."] = "Taille de l'horloge."
L["How big the corner crown is."] = "Taille de la couronne dans le coin."
L["How big the crowd control icon is."] = "Taille de l'icône de contrôle de foule."
L["How big the data texts are."] = "Taille des textes d'informations."
L["How big the dispellable debuff's icon is."] = "Taille de l'icône de l'affaiblissement dissipable."
L["How big the framerate is."] = "Taille de l'affichage des images par seconde."
L["How big the health text is on this frame."] = "Taille du texte de vie sur ce cadre."
L["How big the health text on the tiles is."] = "Taille du texte de vie sur les tuiles."
L["How big the icons of buffs you can purge or steal are."] = "Taille des icônes des améliorations que vous pouvez purger ou voler."
L["How big the item names, counts and skill-up text are in the loot feed."] = "Taille des noms d'objets, des quantités et du texte de progression de compétence dans le flux de butin."
L["How big the large health number is."] = "Taille du grand nombre de vie."
L["How big the leader crown is."] = "Taille de la couronne de chef."
L["How big the leader's crown is."] = "Taille de la couronne du chef."
L["How big the name is on this frame."] = "Taille du nom sur ce cadre."
L["How big the names on the tiles are."] = "Taille des noms sur les tuiles."
L["How big the pets' health text is."] = "Taille du texte de vie des familiers."
L["How big the pets' names are."] = "Taille des noms des familiers."
L["How big the portrait ring is next to the frame's height."] = "Taille de l'anneau du portrait par rapport à la hauteur du cadre."
L["How big the quest marker is in the world, distance text included."] = "Taille du marqueur de quête dans le monde, texte de distance compris."
L["How big the raid marker is."] = "Taille du marqueur de raid."
L["How big the ready check answer is."] = "Taille de la réponse à l'appel."
L["How big the resting Zzz is."] = "Taille du Zzz de repos."
L["How big the role icon is."] = "Taille de l'icône de rôle."
L["How big the round badge of an enemy pet or totem is."] = "Taille du badge rond d'un familier ou totem ennemi."
L["How big the square minimap is."] = "Taille de la minicarte carrée."
L["How big the window is."] = "Taille de la fenêtre."
L["How big the window is. Other windows still open beside it when they fit."] = "Taille de la fenêtre. Les autres fenêtres s'ouvrent toujours à côté quand elles tiennent."
L["How big this extra text is."] = "Taille de ce texte supplémentaire."
L["How big your buff icons on friendly plates are."] = "Taille de vos icônes d'amélioration sur les barres d'info alliées."
L["How big your debuff icons are."] = "Taille de vos icônes d'affaiblissement."
L["How bright the light behind the arrow is."] = "Luminosité de la lumière derrière la flèche."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "Luminosité des points non remplis, en proportion de leur couleur. Plus bas, les points remplis ressortent davantage."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Luminosité des zones inexplorées. À 100%, elles ressemblent aux parties explorées."
L["How dark the shade that sweeps over a button on cooldown is."] = "Obscurité du voile qui balaie un bouton en recharge."
L["How dark the shadow around DaylightUI's frames and windows is."] = "Obscurité de l'ombre autour des cadres et fenêtres de DaylightUI."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "Remplissage de la barre de chaque main : une couleur chacune, le dégradé Daylight (du bleu à l'orange du logo), ou un dégradé bicolore par main, réglé ici. Une attaque en file garde toujours sa propre couleur."
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "Remplissage de chaque barre de sorts (la vôtre, celle de la cible, celle de la focalisation) : une couleur chacune, le dégradé Daylight (du bleu à l'orange du logo), ou un dégradé bicolore par type d'incantation, réglé ici."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "Distance du coin de l'infobulle au-dessus du curseur (sous zéro : plus bas)."
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "Avancement de cet objectif de quête (4/10, ou 45%), en petit, à côté du !."
L["How far away plates show, in yards. 60 is the most the game allows."] = "Distance d'affichage des barres d'info, en mètres. 60 est le maximum permis par le jeu."
L["How far away the spot is."] = "Distance jusqu'à l'endroit."
L["How far from the target the numbers start."] = "Distance de la cible à laquelle les nombres apparaissent."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "Intensité du fondu. À 0, il disparaît complètement. Jamais plus que « Opacité »."
L["How far past the name and bar a click still selects the unit."] = "Distance au-delà du nom et de la barre où un clic sélectionne encore l'unité."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "Distance du coin de l'infobulle à droite du curseur (sous zéro : à gauche)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "Distance de recul maximale de la caméra. 100% est la limite normale du jeu ; l'extrémité droite est le maximum permis par ce client. À 100%, le réglage du jeu n'est pas modifié."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "Inclinaison des extrémités biseautées, sur chaque cadre d'unité et barre de sorts. 21% est l'apparence habituelle."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "Étendue de l'ombre de l'onglet du nom. 0 ne laisse aucune ombre."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "Distance à laquelle les nombres partent sur les côtés. À 0, ils montent tout droit, comme dans le jeu."
L["How far the panel reaches past the buttons on every side."] = "Débord du panneau au-delà des boutons de chaque côté."
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "Étendue de l'ombre douce autour des cadres et fenêtres de DaylightUI."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "Étendue de l'ombre de ce cadre. 0 ne laisse aucune ombre."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "Votre progression dans le niveau, par ex. 24%. Si les nombres sont aussi affichés, elle se place entre eux et les PX de repos."
L["How far through the standing you are, e.g. 60%."] = "Votre progression dans le niveau de réputation, par ex. 60%."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "Écriture des nombres de vie et de ressource sur les cadres d'unité, les textes supplémentaires et les barres d'info. Les pourcentages restent inchangés."
L["How long a line stays on screen before it fades away."] = "Durée d'affichage d'une ligne avant qu'elle ne s'estompe."
L["How long a new item stays in Recent before it goes to its own group."] = "Durée pendant laquelle un nouvel objet reste dans « Récent » avant de rejoindre son propre groupe."
L["How long a new whisper's preview stays."] = "Durée d'affichage de l'aperçu d'un nouveau chuchotement."
L["How long each buff and debuff has left, on the top edge of its icon."] = "Temps restant de chaque amélioration et affaiblissement, sur le bord supérieur de son icône."
L["How long each line stays after your last loot of it."] = "Durée de chaque ligne après votre dernier butin correspondant."
L["How long it stays before fading, unless the buffs land first."] = "Durée avant le fondu, sauf si les améliorations arrivent avant."
L["How long the mouse rests on a link before its tooltip shows, so sweeping across the chat leaves it quiet."] = "Le temps que la souris reste sur un lien avant que son infobulle apparaisse, pour que balayer la discussion ne déclenche rien."
L["How low the enemy's health has to be."] = "Niveau de vie que l'ennemi doit atteindre."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "Nombre de barres à l'écran. Chacune pourra être modifiée séparément plus tard."
L["How many buttons this bar shows."] = "Nombre de boutons affichés par cette barre."
L["How many data texts share the strip. Pick what each shows under Slots."] = "Nombre de textes d'informations sur la bande. Choisissez ce que chacun affiche dans « Emplacements »."
L["How many of the newest messages per chat tab come back after /reload."] = "Nombre de messages les plus récents par onglet de discussion restaurés après /reload."
L["How many people's tiles slide out beside the chat at most."] = "Nombre maximal de tuiles de personnes qui glissent à côté de la discussion."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "Nombre de lignes sur lesquelles se répartissent les boutons (colonnes si la barre est verticale)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "Nombre d'emplacements par ligne du sac. Plus de colonnes le rendent plus large et moins haut."
L["How many yards away it is."] = "Distance en mètres."
L["How much a block, absorb or resist saved you."] = "Ce qu'un blocage, une absorption ou une résistance vous a épargné."
L["How much color the empty part of a bar keeps."] = "Quantité de couleur conservée par la partie vide d'une barre."
L["How much of the health bar's width the row spans, centered."] = "Part de la largeur de la barre de vie couverte par la ligne, centrée."
L["How much the shield can still soak, at the bar's right end."] = "Ce que le bouclier peut encore absorber, à l'extrémité droite de la barre."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "Ce que le bouclier peut encore absorber, sur l'icône à la place de sa durée. Sa taille et sa couleur sont celles des nombres de recharge."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "Affichage de la progression des objectifs : dans les couleurs ci-dessous, en vert une fois terminés, ou du rouge au vert à mesure que le compte augmente."
L["How round the name tab's corners are. 0 keeps them sharp."] = "Arrondi des coins de l'onglet du nom. 0 les garde droits."
L["How round this frame's corners are. 0 keeps them sharp."] = "Arrondi des coins de ce cadre. 0 les garde droits."
L["How see-through a frame gets while its unit is out of range."] = "Transparence d'un cadre quand son unité est hors de portée."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "Transparence d'un sort réglé sur « Fondu », prêt ou en recharge."
L["How see-through a spell set to Fade gets."] = "La transparence d'un sort réglé sur Fondu."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "Transparence de l'icône d'un sort pendant sa recharge. Le temps de recharge global ne compte pas."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "Transparence de chaque fenêtre et panneau : sacs, personnage, grimoire, PNJ, recherche de groupe, les fenêtres du jeu restylées, ainsi que la discussion, le panneau d'informations, le cadre de quêtes et les barres d'améliorations, sauf s'ils ont un réglage distinct sur leur page."
L["How see-through it is while shown, whatever the fade does."] = "Transparence quand il est affiché, quel que soit le fondu."
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "Sa transparence, quand il s'estompe et jusqu'où. Déverrouillé, en mode test ou avec cette page ouverte, il s'affiche à son opacité."
L["How see-through party and raid frames get while a member is out of range."] = "Transparence des cadres de groupe et de raid quand un membre est hors de portée."
L["How see-through the borders around DaylightUI's frames and windows are."] = "Transparence des bordures autour des cadres et fenêtres de DaylightUI."
L["How see-through the info panel's boxes and the meters' own windows are."] = "Transparence des cases du panneau d'informations et des fenêtres des compteurs."
L["How see-through the other plates get while you have a target."] = "Transparence des autres barres d'info quand vous avez une cible."
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "Transparence des symboles de la carte du monde. Diminuez-la pour mieux voir la carte en dessous."
L["How should it look?"] = "Quelle apparence ?"
L["How solid its background is: 0 is fully see-through."] = "Opacité de son fond : 0 est entièrement transparent."
L["How solid the dark background is."] = "Opacité du fond sombre."
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "L'opacité du fond du journal des quêtes. Plus bas, le monde transparaît derrière la liste."
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "Opacité du ruban derrière chaque ligne du flux de butin : 0 est entièrement transparent."
L["How strong the highlight on an active spell is."] = "Intensité de la surbrillance d'un sort actif."
L["How strong the mouseover color over the icon is."] = "Intensité de la couleur de survol sur l'icône."
L["How strong the pressed color over the icon is."] = "Intensité de la couleur d'appui sur l'icône."
L["How strongly it lights up once the enemy is in range."] = "Intensité de l'éclairage une fois l'ennemi à portée."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "Intensité de la teinte de la barre de vie par la couleur de l'affaiblissement. Seulement pour une surbrillance « Teinte » ou « Les deux »."
L["How strongly the spell cost shows on your power bar."] = "Intensité de l'affichage du coût du sort sur votre barre de ressource."
L["How tall a friendly plate's health bar is."] = "Hauteur de la barre de vie d'une barre d'info alliée."
L["How tall each enemy plate's health bar is."] = "Hauteur de la barre de vie de chaque barre d'info ennemie."
L["How tall each line of text over you is. The game's own is 25."] = "Hauteur de chaque ligne de texte au-dessus de vous. Celle du jeu est de 25."
L["How tall each of the threat meter's bars is."] = "Hauteur de chaque barre du compteur de menace."
L["How tall each of this meter's bars is."] = "Hauteur de chaque barre de ce compteur."
L["How tall each pet bar is."] = "Hauteur de chaque barre de familier."
L["How tall each quest's row is in the quest log. Larger text keeps enough room however low this is set."] = "La hauteur de la ligne de chaque quête dans le journal des quêtes. Un texte plus grand garde assez de place, même réglé très bas."
L["How tall each raid tile is."] = "Hauteur de chaque tuile de raid."
L["How tall each swing timer bar is."] = "Hauteur de chaque barre de minuteur d'attaque."
L["How tall each tile's power bar is."] = "Hauteur de la barre de ressource de chaque tuile."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "Hauteur de la barre de vie des autres barres d'info quand vous avez une cible, en proportion de « Hauteur de la barre de vie »."
L["How tall the cast bar under an enemy plate is."] = "Hauteur de la barre de sorts sous une barre d'info ennemie."
L["How tall the experience bar is."] = "Hauteur de la barre d'expérience."
L["How tall the health bar is."] = "Hauteur de la barre de vie."
L["How tall the health bar under the tooltip is."] = "Hauteur de la barre de vie sous l'infobulle."
L["How tall the meter's own window is."] = "Hauteur de la fenêtre du compteur."
L["How tall the pets' power bars are."] = "Hauteur des barres de ressource des familiers."
L["How tall the power bar is."] = "Hauteur de la barre de ressource."
L["How tall the reputation bar is."] = "La hauteur de la barre de réputation."
L["How tall the second meter's window is."] = "Hauteur de la fenêtre du second compteur."
L["How tall the tab holding the name above the frame is."] = "Hauteur de l'onglet contenant le nom au-dessus du cadre."
L["How tall this frame is."] = "Hauteur de ce cadre."
L["How tall your cast bar is."] = "Hauteur de votre barre de sorts."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Hauteur de la barre de sorts de votre focalisation. Pas à l'intérieur du cadre, où elle prend la place de la barre de ressource."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Hauteur de la barre de sorts de votre cible. Pas à l'intérieur du cadre, où elle prend la place de la barre de ressource."
L["How tall your target's health bar is, as a share of Health bar height."] = "Hauteur de la barre de vie de votre cible, en proportion de « Hauteur de la barre de vie »."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "Format du texte de vie sur les barres d'info alliées : un pourcentage, la vie elle-même, la vie sur le maximum, les deux, ou ce qui manque."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "Format du texte de vie : un pourcentage, la vie elle-même, la vie sur le maximum, les deux, ou ce qui manque."
L["How the pets' health text is written."] = "Format du texte de vie des familiers."
L["How the power text is written."] = "Format du texte de ressource."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "Format du texte de vie des tuiles. « Vie manquante » n'affiche rien quand le membre a toute sa vie."
L["How thick the border around each button is."] = "Épaisseur de la bordure autour de chaque bouton."
L["How thick the name tab's outline is. 0 leaves none."] = "Épaisseur du contour de l'onglet du nom. 0 n'en affiche aucun."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "Bordure des améliorations de cette catégorie : une couleur ou un dégradé. Cliquez pour changer."
L["How this extra text writes the health."] = "Format des points de vie dans ce texte supplémentaire."
L["How this extra text writes the power."] = "Format de la ressource dans ce texte supplémentaire."
L["How wide a friendly plate's health bar is."] = "Largeur de la barre de vie d'une barre d'info alliée."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "Largeur de chaque point de combo. Pas tant que les points s'alignent sur la largeur du cadre."
L["How wide each enemy plate's health bar is."] = "Largeur de la barre de vie de chaque barre d'info ennemie."
L["How wide each pet bar is."] = "Largeur de chaque barre de familier."
L["How wide each raid tile is."] = "Largeur de chaque case de raid."
L["How wide every other plate is while you have a target, as a share of Width."] = "Largeur des autres barres d'info quand vous avez une cible, en proportion de la largeur."
L["How wide the bars are."] = "Largeur des barres."
L["How wide the damage meter is, in the panel or in its own window."] = "Largeur du compteur de dégâts, dans le panneau ou dans sa propre fenêtre."
L["How wide the list is."] = "Largeur de la liste."
L["How wide the name tab is when Name tab width is Fixed width."] = "Largeur de l'onglet du nom quand « Largeur de l'onglet du nom » est sur Largeur fixe."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "La largeur de la barre de réputation. Faire glisser son coin en mode déverrouillage la règle aussi."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "Largeur de la fenêtre du second compteur. Faire glisser son coin en mode déverrouillage la règle aussi."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "Largeur de la barre d'expérience séparée. Faire glisser son coin en mode déverrouillage la règle aussi."
L["How wide the threat meter is."] = "Largeur du compteur de menace."
L["How wide this frame is."] = "Largeur de ce cadre."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Largeur de la barre de sorts de votre focalisation. Pas à l'intérieur du cadre, ni quand elle s'aligne sur la largeur du cadre."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Largeur de la barre de sorts de votre cible. Pas à l'intérieur du cadre, ni quand elle s'aligne sur la largeur du cadre."
L["How wide your target's plate is, as a share of Width."] = "Largeur de la barre d'info de votre cible, en proportion de la largeur."
L["How you find your way to quests, and how they show in the tracker."] = "Comment vous trouvez le chemin vers les quêtes, et comment elles s'affichent dans le suivi."
L["How you find your way to quests, how they show in the tracker, and how talking to NPCs looks."] = "Comment vous trouvez vos quêtes, comment elles s'affichent dans le suivi et à quoi ressemble le dialogue avec les PNJ."
L["How your target's plate stands out from the rest."] = "Comment la barre d'info de votre cible se distingue des autres."
L["Hunter"] = "Chasseur"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "Chasseurs : une ligne sur la barre de tir à distance là où commence la préparation du Tir automatique, ajustée selon la hâte et votre latence. Bouger au-delà retient le tir : la barre reste pleine et affiche « Arrêtez de bouger » jusqu'à ce que vous soyez immobile."
L["I'd like to train."] = "Je voudrais m'entraîner."
L["I'm away right now, I'll get back to you soon."] = "Je suis absent pour le moment, je vous réponds bientôt."
L["INTERRUPTS"] = "INTERRUPTIONS"
L["Icon"] = "Icône"
L["Icon (the game's)"] = "Icône (celle du jeu)"
L["Icon look"] = "Aspect des icônes"
L["Icon per class"] = "Icône par classe"
L["Icon positions and sizes"] = "Positions et tailles des icônes"
L["Icon size"] = "Taille des icônes"
L["Icon style"] = "Style des icônes"
L["Icon zoom"] = "Zoom des icônes"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "Les icônes se remplissent depuis le bord droit de la barre vers la gauche, vers le centre de l'écran."
L["Icons left / right"] = "Icônes gauche / droite"
L["Icons on a row before it wraps to the next."] = "Icônes sur une rangée avant de passer à la suivante."
L["Icons on bars"] = "Icônes sur les barres"
L["Icons per row"] = "Icônes par rangée"
L["Icons up / down"] = "Icônes haut / bas"
L["Idle time (seconds)"] = "Temps d'inactivité (secondes)"
L["Ignore"] = "Ignorer"
L["Ignored"] = "Ignoré"
L["Immersive"] = "Immersif"
L["Immersive Preset"] = "Préréglage immersif"
L["Import"] = "Importer"
L["Import profile"] = "Importer un profil"
L["Imported the profile %s."] = "Profil %s importé."
L["In a dungeon or raid"] = "En donjon ou en raid"
L["In a fight"] = "En combat"
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "En groupe ou avec un familier, une petite étiquette dans le coin intérieur supérieur du cadre : votre menace sur lui (à 100%, il se retourne contre vous). Orange quand vous vous en approchez, rouge une fois qu'il vous attaque."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "En groupe, colore un monstre selon qui il attaque ; en solo, les barres d'info ne changent jamais. En tant que tank : rouge quand il attaque quelqu'un d'autre, orange quand vous êtes sur le point de le perdre, normal tant que vous le gardez. En tant que DPS ou soigneur : orange quand vous êtes près de prendre l'aggro, rouge une fois qu'il vous attaque."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "En groupe ou avec un familier, l'anneau de la cible (et l'étiquette de menace) prend cette couleur quand vous êtes près de prendre l'aggro."
L["In a raid, only the leader and assists can use the leader tools."] = "En raid, seuls le chef et les assistants peuvent utiliser les outils de chef."
L["In a row above the bar."] = "En rangée au-dessus de la barre."
L["In categories"] = "Par catégories"
L["In columns"] = "En colonnes"
L["In combat"] = "En combat"
L["In combat in a group or with a pet"] = "En combat en groupe ou avec un familier"
L["In combat, when I'm the tank"] = "En combat, quand je suis le tank"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "En donjon, raid, champ de bataille et arène, tout ce qui est réglé pour s'estomper reste affiché, comme si son fondu était sur Jamais. Le fondu reprend une fois que vous êtes ressorti."
L["In fights"] = "Pendant les combats"
L["In fights and when idle"] = "Pendant les combats et en inactivité"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "Pendant les combats : le panneau et les onglets s'effacent et les messages restent sur le monde. En inactivité : toute la discussion s'estompe aussi quand rien de nouveau n'arrive pendant un moment. Toujours : ni panneau ni onglets pendant que vous jouez, seulement les messages. Survoler la discussion ou appuyer sur Entrée la fait revenir."
L["In progress"] = "En cours"
L["In public channels (General, Trade, say...), the same words from the same person again within a minute are hidden. Guild, group and whispers are never hidden."] = "Dans les canaux publics (Général, Commerce, dire...), les mêmes mots de la même personne répétés en moins d'une minute sont masqués. La guilde, le groupe et les chuchotements ne sont jamais masqués."
L["In rows"] = "En rangées"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "En pixels d'écran, pour rester net à toute échelle d'interface. La bordure épaisse nécessite 3 ou plus."
L["In the Daylight chat box (Chat style: Daylight)."] = "Dans la zone de discussion Daylight (style de discussion : Daylight)."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "Dans la zone de saisie, Haut et Bas parcourent ce que vous avez envoyé. Alt+Haut et Alt+Bas fonctionnent toujours comme avant. Tant que la zone est ouverte, les flèches ne font pas tourner votre personnage."
L["In the group"] = "Dans le groupe"
L["In the info panel"] = "Dans le panneau d'infos"
L["In the tooltip spot"] = "À l'emplacement de l'infobulle"
L["In use"] = "Utilisé"
L["In use: %s"] = "Utilisé : %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "Dans votre couleur d'accent (Apparence), en la suivant quand elle change. Désactivé, utilise la couleur ci-dessous."
L["In your layout: click to pick it."] = "Dans votre disposition : cliquez pour le choisir."
L["Inactive"] = "Inactif"
L["Inbox"] = "Boîte de réception"
L["Incoming heals"] = "Soins entrants"
L["Info"] = "Infos"
L["Info Panel"] = "Panneau d'infos"
L["Info panel"] = "Panneau d'infos"
L["Info panel background opacity"] = "Opacité du fond du panneau d'infos"
L["Inner end"] = "Extrémité intérieure"
L["Inside the frame"] = "À l'intérieur du cadre"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "À l'intérieur du cadre, elle recouvre la barre de ressource, sur toute sa largeur (dans le style Ruban, elle se place plutôt sous le cadre). Au-dessus, en dessous ou indépendante, c'est une barre dont vous réglez la taille ici ; indépendante, vous la déplacez en mode déverrouillage."
L["Inspect"] = "Inspection"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "Inspecter un joueur ouvre la fenêtre de DaylightUI, avec son équipement et ses talents. Désactivez pour utiliser la fenêtre du jeu."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Installez l'addon Jiberish Fabled Icons pour débloquer d'autres styles d'icônes de classe."
L["Instance"] = "Instance"
L["Instance chat, used in battlegrounds and groups made by the group finder."] = "Discussion d'instance, utilisée en champ de bataille et dans les groupes formés par la recherche de groupe."
L["Instance color"] = "Couleur d'instance"
L["Intellect"] = "Intelligence"
L["Interrupt animation"] = "Animation d'interruption"
L["Interrupted"] = "Interrompu"
L["Interrupted color"] = "Couleur d'interruption"
L["Interrupted gradient"] = "Dégradé d'interruption"
L["Interrupts"] = "Interruptions"
L["Into the Void"] = "Dans le Vide"
L["Inventory is full."] = "L'inventaire est plein."
L["Invert gradients"] = "Inverser les dégradés"
L["Invite"] = "Inviter"
L["Ironforge"] = "Forgefer"
L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "Il s'affiche quand le premier compteur s'afficherait : « Afficher seulement en groupe » et « Afficher seulement en combat » de la page Compteur de dégâts valent pour les deux. Réinitialiser efface les combats des deux."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "Il revient une fois le combat terminé. Un clic sur son onglet passe outre jusqu'au début ou à la fin du prochain combat."
L["It takes a reload."] = "Cela nécessite un rechargement."
L["It's %s. Just one more quest?"] = "Il est %s. Encore une petite quête ?"
L["Item"] = "Objet"
L["Item ID"] = "ID d'objet"
L["Item buttons"] = "Boutons d'objet"
L["Item icons"] = "Icônes d'objet"
L["Item level"] = "Niveau d'objet"
L["Item level %s"] = "Niveau d'objet %s"
L["Item level line"] = "Ligne du niveau d'objet"
L["Item names beside icons"] = "Noms des objets à côté des icônes"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "Noms des objets dans la couleur de leur qualité, ou tous en blanc. Le bord de l'icône garde la couleur de qualité."
L["Item quality border"] = "Bordure de qualité d'objet"
L["Items"] = "Objets"
L["Items and loot"] = "Objets et butin"
L["Items below this quality don't show, like gray junk."] = "Les objets en dessous de cette qualité ne s'affichent pas, comme la camelote grise."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "Objets triés en groupes par type. Pour déplacer un objet vers un autre groupe, faites-le glisser sur l'en-tête de ce groupe ou faites Alt-clic droit dessus. Cliquez sur un en-tête pour le replier. Alt-clic droit verrouille aussi un objet pour qu'il ne soit jamais vendu ni désenchanté."
L["Items that are uncommon or better get a border in their quality color."] = "Les objets de qualité inhabituelle ou mieux reçoivent une bordure dans la couleur de leur qualité."
L["Items you loot, create, buy or get from a quest."] = "Les objets que vous ramassez, fabriquez, achetez ou obtenez d'une quête."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "Les objets que votre classe, votre niveau ou vos compétences ne permettent pas encore d'utiliser, ou que vous connaissez déjà, ont une icône rouge, comme chez un marchand."
L["Itim"] = "Itim"
L["Its buff or debuff"] = "Son amélioration ou affaiblissement"
L["Its cooldown"] = "Son temps de recharge"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "Ses fenêtres d'options et My Journey, et ses icônes d'objectifs de quête sur les cartes, chaque quête dans sa propre couleur."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "Son propre fondu, distinct de celui du panneau. Quand cette page est ouverte, un groupe d'exemple s'affiche."
L["Its own window"] = "Sa propre fenêtre"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Sa propre fenêtre, dans le coin inférieur droit au départ. Déplacez-la en mode déverrouillage (/dui unlock) et faites glisser son coin pour la redimensionner."
L["Its owner's class"] = "La classe de son maître"
L["Its owner's class tells at a glance whose pet it is."] = "La classe de son maître indique d'un coup d'œil à qui appartient le familier."
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "Ses boutons d'anneau prennent l'apparence de vos barres d'actions. L'anneau, sa rotation et ses options restent ceux d'OPie."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Ses barres de délai dans votre police, texture de barre et bordure. Tailles, couleurs et emplacements restent ceux de DBM."
L["BigWigs and LittleWigs"] = "BigWigs et LittleWigs"
L["Leader crown left / right"] = "Couronne du chef gauche / droite"
L["Leader crown up / down"] = "Couronne du chef haut / bas"
L["Nudges it sideways from its spot."] = "Le décale latéralement par rapport à son emplacement."
L["Nudges it up or down from its spot."] = "Le décale vers le haut ou le bas par rapport à son emplacement."
L["Party pet"] = "Familier de groupe"
L["Ready check left / right"] = "Appel gauche / droite"
L["Ready check up / down"] = "Appel haut / bas"
L["Role icon left / right"] = "Icône de rôle gauche / droite"
L["Role icon up / down"] = "Icône de rôle haut / bas"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Leurs barres de délai dans votre police, texture de barre et bordure, avec le style de barre Default de BigWigs. Tailles, couleurs et emplacements restent ceux de BigWigs."
L["Its window, and each attunement chain drawn like the talent trees."] = "Sa fenêtre, et chaque chaîne d'harmonisation dessinée comme les arbres de talents."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "Jiberish Fabled Icons est installé. Choisissez une icône pour chaque classe ci-dessous, n'importe quel style ou l'une de ses spécialisations. La première icône de chaque ligne suit le style des icônes."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "Rejoignez un groupe pour utiliser les outils de chef, ou essayez-les avec /dui leader test."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Rejoignez le Discord de DaylightUI : appuyez sur Ctrl+C pour copier le lien, puis collez-le dans votre navigateur."
L["Junk"] = "Camelote"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Juste à gauche du panneau, aligné sur son haut, en le suivant quand la minicarte ou le compteur de dégâts change de taille. Désactivez pour déplacer la barre vous-même en mode déverrouillage."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Juste à gauche du panneau, la première rangée posée sur son bord inférieur, en le suivant quand la minicarte ou le compteur de dégâts change de taille. Désactivez pour déplacer la barre vous-même en mode déverrouillage."
L["Just this spell, for now"] = "Seulement ce sort, pour l'instant"
