L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems. General uses the font on General > Appearance."] = "Raccourcis, nombres de charges, noms de macro et chiffres de temps de recharge sur toutes les barres, le gestionnaire de temps de recharge et les totems. Général utilise la police de Général > Apparence."
L["Keys"] = "Clés"
L["Kicked by"] = "Interrompu par"
L["Kinds: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nBinding: boe, bou, soulbound. In an equipment set: set, or the set's name. Locked: locked\nQuality: poor, common, uncommon, rare, epic, legendary, or q>rare, q>=uncommon, q<epic\nItem level: ilvl>20, ilvl<=10, ilvl20-30\nJoin with & (all) or | (any), ! for not: boe & q>common, food | potion, gear & !set\nA word that isn't one of these finds names. Start with # for the keyword only."] = "Types : gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nLiaison : boe, bou, soulbound. Dans un ensemble d'équipement : set, ou le nom de l'ensemble. Verrouillé : locked\nQualité : poor, common, uncommon, rare, epic, legendary, ou q>rare, q>=uncommon, q<epic\nNiveau d'objet : ilvl>20, ilvl<=10, ilvl20-30\nCombinez avec & (tous) ou | (au moins un), ! pour la négation : boe & q>common, food | potion, gear & !set\nUn mot qui n'en fait pas partie cherche dans les noms. Commencez par # pour le mot-clé seul."
