L["Loot, money, XP, reputation and skill-ups don't bring the chat back, so it stays out of the way while you grind. Whispers, party, guild and other messages still do."] = "Le butin, l'argent, les PX, la réputation et les gains de compétence ne font pas revenir la discussion, pour qu'elle reste discrète pendant que vous farmez. Les chuchotements, messages de groupe, de guilde et autres la font toujours revenir."
L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "Les objets de quête ramassables scintillent, tout comme les donneurs de quête (le jeu n'a pas de réglage pour un seul des deux). Le jeu ne fait scintiller que si son contour autour de ce que vous pointez est désactivé, donc cette option le garde désactivé. Désactiver cette option remet le contour ; le scintillement peut rester jusqu'au redémarrage du jeu."
