L["Old layout: %s, set %d"] = "Ancienne disposition : %s, ensemble %d"
L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "Pendant un vol, une barre en haut de l'écran indique votre destination et le temps restant. La durée de chaque trajet est apprise la première fois que vous l'effectuez, pour tous vos personnages. Déplacez-la avec /dui unlock."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "Lors d'un appel, et quand vous entrez dans un donjon ou un raid en groupe, une courte ligne indique les améliorations de groupe qu'il vous manque : seulement celles que quelqu'un de votre groupe peut donner. Elle s'efface une fois qu'elles sont appliquées. Déplacez-la en mode déverrouillage."
L["On cooldown"] = "En recharge"
L["On in the Healer setup. Each class has its own picks; change them below."] = "Activé dans la configuration Soigneur. Chaque classe a ses propres choix ; modifiez-les ci-dessous."
L["On its own (unlock to move)"] = "Indépendante (déverrouiller pour déplacer)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "Indépendante, la barre de ressource quitte le cadre et vous pouvez la déplacer n'importe où en mode déverrouillage, par exemple au centre de l'écran. Le cadre n'affiche alors que la vie."
L["On the plate"] = "Sur la barre d'info"
L["On the portrait"] = "Sur le portrait"
L["On the portrait rings of the player, target and focus frames."] = "Sur les anneaux de portrait des cadres du joueur, de la cible et de la focalisation."
L["One click sets where the auras and the name sit. Change anything after."] = "Un clic définit où se placent les auras et le nom. Modifiez ce que vous voulez ensuite."
L["One color"] = "Une couleur"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "Une couleur sur chaque point ; des couleurs passant de « Couleur des points de combo » à « Couleur pleine » le long de la rangée ; votre couleur de classe ; ou des paires de deux couleurs de la page Dégradés (Points de combo), une pour tous les points ou une pour chacun. Les points de combo de vos barres d'info utilisent les mêmes couleurs."
L["One custom color, the accent, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Une couleur personnalisée, l'accent, la couleur de votre classe, ou les deux couleurs de votre classe en dégradé (de la page Dégradés)."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Une couleur personnalisée, votre couleur de classe, ou les deux couleurs de votre classe en dégradé (depuis la page Dégradés)."
L["One gradient (Gradients page)"] = "Un dégradé (page Dégradés)"
L["One more thing at the end of the same line, after the second part."] = "Un élément de plus à la fin de la même ligne, après la deuxième partie."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "Une rangée par membre du groupe, plus votre familier, sur la liste de menace de votre cible, du plus élevé au plus bas, vous y compris toujours. Le pourcentage se rapporte au seuil d'aggro : à 100%, il se retourne contre vous."
L["One switch per part of the game's windows."] = "Un interrupteur par partie des fenêtres du jeu."
L["One tile with the count"] = "Une case avec le nombre"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Une case : chaque section de la banque affiche un seul emplacement vide portant le nombre d'emplacements libres. Déposez-y un objet pour l'y ranger."
L["One tile: each section shows a single empty slot with the free count on it."] = "Une case : chaque section affiche un seul emplacement vide portant le nombre d'emplacements libres."
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Une case : chaque section affiche un seul emplacement vide portant le nombre d'emplacements libres. Déposez-y un objet pour l'y ranger."
L["Ones that matter in a fight"] = "Ceux qui comptent en combat"
L["Online"] = "En ligne"
L["Only at full health"] = "Seulement à pleine vie"
L["Only clears this list. Moved buffs stay in their new categories."] = "Efface seulement cette liste. Les améliorations déplacées restent dans leurs nouvelles catégories."
L["Only debuffs I can dispel"] = "Seulement les affaiblissements que je peux dissiper"
L["Only enemies"] = "Ennemis seulement"
L["Only in a group"] = "Seulement en groupe"
L["Only in combat"] = "Seulement en combat"
L["Only mine"] = "Seulement les miens"
L["Only ones I can dispel"] = "Seulement ceux que je peux dissiper"
L["Only spells you cast can be bound."] = "Seuls les sorts que vous lancez peuvent être assignés."
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "Seuls les messages de la discussion restent sur le monde, chacun s'estompant après un moment, comme la discussion flottante (Discussion > Flottant). Cela reste actif même avec « Tout estomper au feu de camp » activé."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "Seulement les affaiblissements que vous lui appliquez, ou les vôtres d'abord puis ceux des autres."
L["Only under a minute"] = "Seulement sous une minute"
L["Only when detached."] = "Seulement quand détaché."
L["Only when detached. Main hand at the bottom, the others above it."] = "Seulement quand détaché. Main droite en bas, les autres au-dessus."
L["Only when detached. When attached, the bars match the cast bar's width."] = "Seulement quand détaché. Attachées, les barres s'alignent sur la largeur de la barre de sorts."
L["Only when something changes"] = "Seulement quand quelque chose change"
L["Only while the power bar is on its own."] = "Seulement quand la barre de ressource est indépendante."
L["Only while the power bar is on its own. When off, both ends are straight."] = "Seulement quand la barre de ressource est indépendante. Désactivé, les deux extrémités sont droites."
L["Only with a target"] = "Seulement avec une cible"
L["Only your group's leader can change the listing."] = "Seul le chef de votre groupe peut modifier l'annonce."
L["Only your group's leader can list the group."] = "Seul le chef de votre groupe peut inscrire le groupe."
L["Opacity"] = "Opacité"
L["Opacity & fade"] = "Opacité et fondu"
L["Opacity on cooldown"] = "Opacité en recharge"
L["Open"] = "Ouvrir"
L["Open DaylightUI options"] = "Ouvrir les options de DaylightUI"
L["Open a chat box first to link it."] = "Ouvrez d'abord une zone de saisie de discussion pour le lier."
L["Open spot"] = "Place libre"
L["Open stat groups"] = "Groupes de caractéristiques ouverts"
L["Open this page at these settings."] = "Ouvrir cette page sur ces réglages."
L["Open world only"] = "Monde extérieur uniquement"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "Ouvrir une boîte aux lettres affiche la fenêtre de DaylightUI : vos lettres, l'envoi et un registre de votre or. Désactivez-la pour utiliser la fenêtre du jeu. Le registre continue de compter dans tous les cas."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "Ouvrir un métier affiche la fenêtre de DaylightUI : vos recettes à gauche, celle choisie à droite. En combat, c'est la fenêtre du jeu qui s'ouvre. Désactivez-la pour utiliser la fenêtre du jeu."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "Ouvrir un marchand vend tout le groupe Camelote : les objets gris et tout ce que vous y avez déplacé vous-même. La discussion indique combien vous avez gagné."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "Ouvrir un marchand qui répare remet en état tout votre équipement, et la discussion indique le coût. Pas en combat."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "Ouverture et fermeture des fenêtres : sacs, personnage, grimoire, journal des quêtes, menu du jeu et fenêtres de DaylightUI."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "Ouvrir la recherche de groupe affiche la fenêtre de DaylightUI : groupes à rejoindre, votre inscription et qui est dans les parages. En combat, c'est la fenêtre du jeu qui s'ouvre. Désactivez-la pour utiliser la fenêtre du jeu."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "Ouvrir votre sac complète les piles partielles d'un même objet (15 et 5 Étoffes de lin deviennent 20), pour ne gaspiller aucun emplacement. Pas en combat, ni pendant un échange ou avec la boîte aux lettres ou l'hôtel des ventes ouverts."
L["Opens the Gradients page, where the Combo points pairs are."] = "Ouvre la page Dégradés, où se trouvent les paires des points de combo."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Ouvre l'éditeur de disposition directement à l'écran : tirez des sorts depuis la réserve, faites-les glisser où vous voulez, reliez-les, cliquez sur l'un d'eux pour le modifier. Tapez /cdm pour l'ouvrir à tout moment. Hors combat uniquement."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "Ouvre votre grimoire avec le clic-incantation activé : cliquez sur un sort avec le bouton de souris voulu. Fermez le grimoire une fois terminé et cette page revient."
L["Option toggles"] = "Interrupteurs d'options"
L["Options"] = "Options"
