L["Over an hour away. Still here, still waiting."] = "Absent depuis plus d'une heure. Toujours là, toujours en attente."
L["Over its owner"] = "Au-dessus de son propriétaire"
L["Over or under the frame, the buffs sit nearest it when both share a spot. Outside spots may need room around the frame."] = "Au-dessus ou en dessous du cadre, les améliorations sont les plus proches quand les deux partagent une position. Les positions extérieures peuvent nécessiter de la place autour du cadre."
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "Au-dessus, en dessous ou à côté de la barre de vie. En mode Conception sur l'aperçu, faites-le glisser à l'endroit voulu."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Au-dessus, en dessous ou à côté de la barre de vie. Les rangées qui partagent une position s'alignent vers l'extérieur depuis la barre. En mode Conception sur l'aperçu, faites-le glisser à l'endroit voulu."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "Au-dessus, en dessous, à côté ou sur la barre de vie d'une barre d'info amicale. Sans barre de vie, le nom reste centré."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Au-dessus, en dessous, à côté ou sur la barre de vie. Les éléments qui partagent une position s'alignent vers l'extérieur depuis la barre. En mode Conception sur l'aperçu, faites-le glisser à l'endroit voulu."
