L["Paste a DaylightUI profile (Ctrl+V) and name it. It becomes a new profile, chosen for this character (these talents, with dual spec); yours stay as they are."] = "Collez un profil DaylightUI (Ctrl+V) et nommez-le. Il devient un nouveau profil, choisi pour ce personnage (ces talents, avec la double spécialisation) ; les vôtres restent tels quels."
