L["Players"] = "Joueurs"
L["Players' and creatures' tooltips show while you're fighting. When off, they stay hidden in a fight; hold Shift to see one."] = "Les infobulles des joueurs et des créatures s'affichent pendant le combat. Désactivé, elles restent masquées en combat ; maintenez Maj pour en voir une."
L["Players' last names after their first, on nameplates. Where the game hides names (in combat, in places) only the first name shows."] = "Le nom de famille des joueurs après leur prénom, sur les barres d'info. Là où le jeu masque les noms (en combat, à certains endroits), seul le prénom s'affiche."
L["Players' last names after their first, on this frame only. Where the game hides names (in combat, in places) only the first name shows."] = "Le nom de famille des joueurs après leur prénom, sur ce cadre uniquement. Là où le jeu masque les noms (en combat, à certains endroits), seul le prénom s'affiche."
L["Players' last names after their first, on tooltips. Where the game hides names (in combat, in places) only the first name shows."] = "Le nom de famille des joueurs après leur prénom, dans les infobulles. Là où le jeu masque les noms (en combat, à certains endroits), seul le prénom s'affiche."
L["Players' last names after their first. When off, first names only, which fit the narrow rows better."] = "Le nom de famille des joueurs après leur prénom. Désactivé, seulement le prénom, qui tient mieux dans les rangées étroites."
L["Players' names in their class color, in every kind of chat (the game's own setting)."] = "Le nom des joueurs dans la couleur de leur classe, dans tous les types de discussion (réglage du jeu)."
