L["Preset"] = "Préréglage"
L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "Appuyez sur 1 à 9 pour choisir une ligne ou une récompense, Espace pour l'étape suivante (accepter, continuer, terminer), Échap pour revenir. Espace ne fait jamais sauter pendant le dialogue. Les autres touches vont toujours au jeu, et en combat toutes les touches reviennent au jeu."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "Appuyez sur Associer dans le grimoire (ou ouvrez %s et activez le clic-incantation en haut), puis cliquez sur un sort avec le bouton de souris voulu (maintenez Maj, Ctrl ou Alt pour plus de choix). Ce clic sur n'importe lequel de vos cadres d'unité lancera alors ce sort sur cette unité. Fermez le grimoire une fois terminé : cette page revient. Le clic gauche cible toujours et le clic droit ouvre le menu, sauf si vous les associez."
L["Press Start 2P"] = "Press Start 2P"
L["Press Train again: it takes a profession slot"] = "Appuyez de nouveau sur Apprendre : cela occupe un emplacement de métier"
