L["Pressing O shows DaylightUI's window: who's online, people you played with, friend requests and your raid's groups. Turn it off to use the game's window."] = "Appuyer sur O affiche la fenêtre de DaylightUI : qui est en ligne, les joueurs avec qui vous avez joué, les demandes d'ami et les groupes de votre raid. Désactivez-la pour utiliser la fenêtre du jeu."
