L["Puts the zone you're in at the top of the quest log. When off, zones stay in the game's order."] = "Place la zone où vous êtes en haut du journal des quêtes. Désactivé, les zones restent dans l'ordre du jeu."
L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's. Damage numbers follow it too, unless their own page picks a font."] = "Applique aussi cette police aux textes du jeu : menus, infobulles, textes de quête, fenêtres surgissantes, noms des barres d'info. Les tailles et contours restent ceux du jeu. Les chiffres de dégâts la suivent aussi, sauf si leur propre page choisit une police."
