L["Sets Visible to Only when something changes on every part that has it: gone out of a fight, back in one, and back for a moment when it changes. Turned off, each goes back to its default. Each part's own Visible on its page still works on its own."] = "Règle Visible sur Seulement en cas de changement pour chaque élément qui le propose : masqué hors combat, de retour en combat, et brièvement de retour lorsqu'il change. Désactivé, chacun revient à sa valeur par défaut. Le réglage Visible propre à chaque élément sur sa page continue de fonctionner indépendamment."
L["Sets every category to Combine, so each shows as one icon. Click None to set them all back."] = "Règle toutes les catégories sur Combiner, pour que chacune s'affiche en une seule icône. Cliquez sur Aucun pour toutes les rétablir."
L["Sets every pair back to the palette's colors. Gradient direction and Invert gradients are kept."] = "Rétablit toutes les paires aux couleurs de la palette. La direction du dégradé et l'inversion des dégradés sont conservées."
