L["Shows a grid while frames are unlocked, and snaps them to it."] = "Affiche une grille quand les cadres sont déverrouillés, et les y aimante."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "Affiche une poignée sur chaque cadre. Faites-la glisser pour le déplacer ; clic droit sur une poignée pour réinitialiser ce cadre."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "Affiche le nom d'une macro sur son bouton. Désactivé, les macros n'affichent que leur icône."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "Affiche un exemple de ce seul cadre pendant que vous le modifiez, avec chaque changement au fur et à mesure. Reste actif d'une page à l'autre jusqu'à ce que vous le désactiviez ; le combat y met fin."
L["Shows a sample of the line where it sits."] = "Affiche un exemple de la ligne à son emplacement."
L["Shows buffs icons on each member."] = "Affiche les icônes d'amélioration sur chaque membre."
L["Shows crowd control icons on each member."] = "Affiche les icônes de contrôle de foule sur chaque membre."
L["Shows debuffs icons on each member."] = "Affiche les icônes d'affaiblissement sur chaque membre."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "Affiche le raccourci de chaque bouton sur celui-ci. Désactivé, les raccourcis fonctionnent toujours, ils ne sont simplement plus visibles."
L["Shows each pet's health as text."] = "Affiche la vie de chaque familier sous forme de texte."
L["Shows each pet's name."] = "Affiche le nom de chaque familier."
L["Shows only while the buff is up, like Power Word: Shield."] = "S'affiche uniquement tant que l'amélioration est active, comme Mot de pouvoir : Bouclier."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "Affiche ou masque la rangée de boutons des sacs. Vos raccourcis de sacs les ouvrent toujours lorsqu'elle est masquée."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "Affiche ou masque la rangée de petits boutons qui ouvrent les fenêtres du personnage, du grimoire, des talents et autres. Leurs raccourcis fonctionnent toujours lorsqu'elle est masquée."
L["Shows server time instead of your local time."] = "Affiche l'heure du serveur au lieu de votre heure locale."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "Affiche la cible, la focalisation, le familier, la cible de la cible et le groupe avec des unités d'exemple, ainsi que les deux barres de sorts en cours d'incantation, pour les personnaliser et les déplacer sans vraie cible. Prend fin au début d'un combat."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "Affiche l'écran ABS maintenant. Cliquez ou appuyez sur une touche pour le fermer. Aussi /dui afk."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "Affiche les boutons du calendrier et du suivi sur le bord droit de la carte lorsque la souris survole la carte."
L["Shows the game's countdown on buttons that are on cooldown."] = "Affiche le compte à rebours du jeu sur les boutons en temps de recharge."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "Affiche la petite pièce d'or du jeu sur les objets gris de la banque, comme les sacs par défaut."
L["Shows the game's small gold coin on gray items, like the default bags."] = "Affiche la petite pièce d'or du jeu sur les objets gris, comme les sacs par défaut."
L["Shows the healer's name next to a heal on you."] = "Affiche le nom du soigneur à côté d'un soin reçu."
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "Affiche le texte de vie en grand et en blanc dans le coin intérieur du cadre (en Ruban, à l'extrémité intérieure de la ligne au-dessus de la barre)."
L["Shows the unit's name on this frame."] = "Affiche le nom de l'unité sur ce cadre."
L["Shows these raid frames in a party too, in place of the party frames."] = "Affiche aussi ces cadres de raid en groupe, à la place des cadres de groupe."
L["Shows this square on each member while its spell is on them."] = "Affiche ce carré sur chaque membre tant que son sort est actif sur lui."
L["Shows where the range is before the enemy gets there, faintly."] = "Indique discrètement où se trouve la portée avant que l'ennemi ne l'atteigne."
L["Shrink icon when pressed"] = "Réduire l'icône à l'appui"
