L["Since %s"] = "Depuis %s"
L["Since you logged in"] = "Depuis votre connexion"
L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "Assis près d'un feu de camp, l'écran se réchauffe de lueurs et de braises, un doux crépitement se fait entendre et vos barres d'actions et cadres d'unité s'effacent. Bougez, ciblez ou incantez et tout réapparaît ; un combat les fait revenir aussitôt. Les sons suivent Sons d'interface doux (Général > Son)."
