L["Size of the numbers on the experience bar."] = "Taille des nombres sur la barre d'expérience."
L["Size of the quest names in the quest log on the map. Zone names, levels and progress follow it."] = "Taille des noms de quêtes dans le journal des quêtes sur la carte. Les noms de zones, les niveaux et la progression suivent."
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "Taille du texte sur la barre de réputation. Sa police est celle de la barre d'expérience."
