L["Slot size"] = "Taille des emplacements"
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for Bank and alts alone: their rows show below."] = "La taille des emplacements, l'espacement, l'échelle, la disposition des objets, les emplacements vides et les marques sur les icônes suivent votre page Sacs. Désactivez cette option pour les régler séparément pour Banque et personnages secondaires : leurs lignes s'affichent ci-dessous."
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "La taille des emplacements, l'espacement, l'échelle, la disposition des objets, les emplacements vides et les marques sur les icônes suivent votre page Sacs. Désactivez cette option pour les régler séparément pour la banque : leurs lignes s'affichent ci-dessous."
L["Slots"] = "Emplacements"
L["Slots per row in the Bank and alts window."] = "Emplacements par ligne dans la fenêtre Banque et personnages secondaires."
L["Slots per row in the bank. It holds more than your bags, so it's wider by default."] = "Emplacements par ligne dans la banque. Elle contient plus que vos sacs, elle est donc plus large par défaut."
L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "Les emplacements vides s'affichent comme des cadres vides. Désactivé, ils disparaissent et réapparaissent lorsque vous faites glisser un sort ou un objet."
L["Small Brown Pouch"] = "Petite bourse marron"
L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "Petits carrés colorés sur chaque membre pour vos soins sur la durée et boucliers, comme Rénovation ou Mot de pouvoir : Bouclier. Chaque carré s'affiche tant que votre sort est actif sur lui."
L["Small helpers and the game's windows in DaylightUI style."] = "Petits assistants et fenêtres du jeu au style DaylightUI."
L["Small helpers for looting, quests, trainers and more."] = "Petits assistants pour le butin, les quêtes, les maîtres et plus encore."
L["Small helpers that save time every day. Each one says what it does."] = "Petits assistants qui font gagner du temps au quotidien. Chacun explique ce qu'il fait."
L["Small helpers: faster looting, quest automation, trainers and more."] = "Petits assistants : butin plus rapide, automatisation des quêtes, maîtres et plus encore."
L["Small icons in their own row, under the frame by default."] = "Petites icônes sur leur propre ligne, sous le cadre par défaut."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "Petites icônes au-dessus de votre cadre, au plus près. Désactivé par défaut : vos barres d'amélioration les affichent aussi."
L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "Petites cases pour un raid jusqu'à 10 : une colonne par groupe, de gauche à droite. L'affichage, le fondu, les textures et les polices définis ici valent pour toutes les tailles de raid ; votre groupe a sa propre page."
