L["Some boss abilities put debuffs on you that addons can't see. The game draws them itself, in a row under your debuffs."] = "Certaines techniques de boss vous appliquent des affaiblissements que les addons ne voient pas. Le jeu les affiche lui-même, sur une ligne sous vos affaiblissements."
