L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. Closing the spellbook switches it off. /dui > Unit Frames > Click-casting lists them."] = "Activez, puis cliquez sur un sort avec le bouton de souris voulu (maintenez Maj, Ctrl ou Alt pour d'autres combinaisons) : ce clic sur un cadre d'unité le lancera. Fermer le grimoire désactive ce mode. /dui > Cadres d'unité > Lancement au clic les répertorie."
