L["Talking to an NPC opens DaylightUI's window for gossip, quests and rewards. Turn it off to use the game's own windows."] = "Parler à un PNJ ouvre la fenêtre DaylightUI pour les discussions, quêtes et récompenses. Désactivez cette option pour utiliser les fenêtres du jeu."
