L["Text size for every chat window. Set to 0 to keep each window's own size (set in its tab menu)."] = "Taille du texte pour toutes les fenêtres de discussion. Réglez sur 0 pour conserver la taille propre à chaque fenêtre (définie dans le menu de son onglet)."
