L["Thank you for making DaylightUI possible."] = "Merci de rendre DaylightUI possible."
L["Thank you to everyone who supports DaylightUI and keeps it growing."] = "Merci à toutes celles et ceux qui soutiennent DaylightUI et le font grandir."
L["That border in the unit's class (or reaction) gradient from the Gradients page, running left to right."] = "Cette bordure dans le dégradé de classe (ou de réaction) de l'unité défini sur la page Dégradés, de gauche à droite."
L["That's as many builds as a set keeps: delete one first."] = "Ce jeu contient déjà le nombre maximal de configurations : supprimez-en une d'abord."
L["The '?', the title and the hand-in line."] = "Le « ? », le titre et la ligne de rendu."
L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "L'écran ABS ne peut pas s'afficher en combat, contre un boss, en donjon mythique+ ou en match JcJ."
L["The Daylight chat box's own look and motion (Chat style: Daylight)."] = "L'apparence et les animations propres à la zone de discussion Daylight (style de discussion : Daylight)."
L["The DaylightUI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "La bordure DaylightUI, la couleur de qualité de l'objet, votre couleur d'accent (Général > Apparence), ou une couleur de votre choix."
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "Les styles Fabled sont l'œuvre de JiberishUI et de ses artistes. Ils proviennent de l'addon Jiberish Fabled Icons, lus depuis son propre dossier. S'il n'est pas installé, chaque style affiche les icônes de Daylight UI."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "Le bouton Héritage affiche la fenêtre DaylightUI : la distance jusqu'à la prochaine récompense, les défis et les arbres d'héritage. Désactivez cette option pour utiliser la fenêtre du jeu."
L["The Mindless Ones completed."] = "Les Sans-esprit terminée."
L["The NPC window is switched off (/dui > Talk)."] = "La fenêtre des PNJ est désactivée (/dui > Dialogue)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "L'en-tête Quêtes reste affiché quand rien n'est suivi, pour que vous voyiez où se trouve le suivi."
L["The accent"] = "L'accent"
L["The aggro color when Aggro color is Custom color."] = "La couleur d'aggro lorsque Couleur d'aggro est réglée sur Couleur personnalisée."
L["The arrow's color while Arrow color is set to Custom."] = "La couleur de la flèche lorsque Couleur de la flèche est réglée sur Personnalisée."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "La banque avec la même apparence que vos sacs. Les groupes et objets déplacés sont partagés avec vos sacs."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "La barre passe du sombre au clair dans les couleurs de son niveau de réputation, modifiables sur la page Dégradés."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "La barre passe du sombre au clair au lieu d'une couleur unie. La réputation en a un par niveau, modifiable sur la page Dégradés."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "La couleur de la barre pour les joueurs morts et hors ligne, les PNJ revendiqués, et pour les PNJ selon leur attitude envers vous."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "La couleur de la barre lorsque l'incantation ne peut pas être interrompue, quel que soit le style de remplissage."
L["The bar's color while the cast can't be interrupted."] = "La couleur de la barre lorsque l'incantation ne peut pas être interrompue."
L["The bars over enemies' heads: how big they are, and what they show."] = "Les barres au-dessus de la tête des ennemis : leur taille et ce qu'elles affichent."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "Les barres passent du sombre au clair au lieu d'une couleur unie. Les paires de couleurs se trouvent dans Général > Dégradés."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "Les barres qui prolongent la vie pour les soins entrants et les boucliers d'absorption. Un surbouclier (un bouclier plus grand que la vie manquante) suit le bouclier."
L["The bars' and names' colors on every unit frame."] = "Les couleurs des barres et des noms sur tous les cadres d'unité."
L["The bars' color when Bar color is One color."] = "La couleur des barres lorsque Couleur de la barre est réglée sur Une couleur."
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "La couleur de bordure de chaque ligne du fil de butin lorsque Couleur de bordure du fil de butin est réglée sur Personnalisée."
L["The border color when Border color is set to Your own color."] = "La couleur de bordure lorsque Couleur de bordure est réglée sur Votre couleur."
L["The border in the same color as the name."] = "La bordure de la même couleur que le nom."
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "La bordure d'un affaiblissement que vous pouvez dissiper, et l'icône de dissipation de la case de raid. Les affaiblissements déjà à l'écran changent après /reload."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "Les cadres derrière la barre d'expérience, la minicarte et le compteur de dégâts, ainsi que les fenêtres des compteurs et du compteur de menace. À une opacité de 0, les cadres disparaissent ; la minicarte et les barres restent affichées."
L["The buffs wrap onto up to this many rows."] = "Les améliorations se répartissent sur ce nombre de lignes au maximum."
L["The button's border lights up while the mouse is over it."] = "La bordure du bouton s'illumine lorsque la souris le survole."
L["The button's border lights up while you press it."] = "La bordure du bouton s'illumine lorsque vous appuyez dessus."
L["The cast bar's color when Fill style is One color."] = "La couleur de la barre de sorts lorsque Style de remplissage est réglé sur Une couleur."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "La fenêtre du personnage et ses onglets (réputation, compétences, JcJ, monnaies, statistiques), l'inspection des autres."
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "Les boutons du menu de discussion, des canaux, de la voix et du social à côté de la discussion. Désactivé, ils disparaissent ; leurs commandes slash fonctionnent toujours."
L["The chat only"] = "La discussion uniquement"
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "Le texte de la fenêtre de discussion et les bulles de dialogue. Général utilise la police de Général > Apparence."
L["The clock reads 18:30 instead of 6:30 PM."] = "L'horloge affiche 18:30 au lieu de 6:30 PM."
L["The color of a Curse debuff's border and dispel icon."] = "La couleur de la bordure et de l'icône de dissipation d'un affaiblissement de type Malédiction."
L["The color of a Disease debuff's border and dispel icon."] = "La couleur de la bordure et de l'icône de dissipation d'un affaiblissement de type Maladie."
L["The color of a Magic debuff's border and dispel icon."] = "La couleur de la bordure et de l'icône de dissipation d'un affaiblissement de type Magie."
L["The color of a Poison debuff's border and dispel icon."] = "La couleur de la bordure et de l'icône de dissipation d'un affaiblissement de type Poison."
L["The color of the glow around your target's bar."] = "La couleur de la lueur autour de la barre de votre cible."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "La couleur du dernier point, ou de toute la rangée au maximum de points, et la fin de Couleur jusqu'à plein."
L["The color of the names on the threat meter."] = "La couleur des noms sur le compteur de menace."
L["The color of the names on this meter's bars."] = "La couleur des noms sur les barres de ce compteur."
L["The color of the outline around your target's bar."] = "La couleur du contour autour de la barre de votre cible."
L["The color of the pull line across the threat bars."] = "La couleur de la ligne de reprise d'aggro sur les barres de menace."
L["The color of the shaded spell cost on your power bar."] = "La couleur du coût du sort ombré sur votre barre de ressource."
L["The color of the stretch for damage shields."] = "La couleur de la portion pour les boucliers de dégâts."
L["The color of the stretch past the health for heals on their way."] = "La couleur de la portion au-delà de la vie pour les soins en cours."
L["The color the border lights up in while the mouse is over a button."] = "La couleur d'illumination de la bordure lorsque la souris survole un bouton."
L["The color the border lights up in while you press a button."] = "La couleur d'illumination de la bordure lorsque vous appuyez sur un bouton."
L["The color the execute range lights up in."] = "La couleur d'illumination de la zone d'exécution."
L["The color used while the menu above is set to Custom."] = "La couleur utilisée lorsque le menu ci-dessus est réglé sur Personnalisée."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "Le balayage coloré sur l'icône tant que son amélioration est active. Désactivé, seul le minuteur s'affiche."
L["The colors below"] = "Les couleurs ci-dessous"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "Les couleurs, la police et les textures utilisées partout. L'écran change au fil de vos choix."
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "La couleur du bord du temps de recharge lorsque Bord du temps de recharge est réglé sur Votre couleur."
L["The cooldown layout can't be edited during combat."] = "La disposition des temps de recharge ne peut pas être modifiée en combat."
L["The cooldown manager's layout."] = "La disposition du gestionnaire de temps de recharge."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "Les icônes de compte à rebours de vos totems, au-dessus du cadre du joueur. Déplacez-les en mode déverrouillage."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "Les monnaies que vous suivez (telles que la liste du sac à dos du jeu les affiche), avec leur icône et leur quantité, à côté de votre argent."
L["The dark part shrinks away instead of filling in."] = "La partie sombre se réduit au lieu de se remplir."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "Le ruban sombre derrière chaque ligne. Désactivé, seuls l'icône et le texte s'affichent."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "Les textes d'information, ainsi que l'horloge et les images par seconde sur la minicarte. Général utilise la police de Général > Apparence."
L["The debuffs wrap onto up to this many rows."] = "Les affaiblissements se répartissent sur ce nombre de lignes au maximum."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "La ligne atténuée sous le nom de chaque objet. Les alertes de réparation s'affichent toujours lorsqu'elle est désactivée."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "Le guide des donjons, ses fenêtres de favoris et de paramètres ; l'image de chaque donjon est conservée."
L["The edge round each button. A proc still lights it up."] = "Le bord autour de chaque bouton. Un déclenchement l'illumine toujours."
L["The elite dragon wraps your own portrait too."] = "Le dragon élite entoure aussi votre propre portrait."
L["The empty bar pulses while the buff is down."] = "La barre vide pulse tant que l'amélioration est absente."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "La partie vide derrière le remplissage de chaque barre, teintée de la couleur de la barre, sauf si la page propre d'un cadre en choisit une autre."
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "La partie vide derrière les barres des fenêtres DaylightUI. Général utilise le fond de barre ci-dessus."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "La partie vide de chaque barre du groupe. Le fond propre d'un sort, ci-dessus, est prioritaire."
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "La partie vide de chaque barre de vie : une copie atténuée de la couleur de la barre, ou une couleur de votre choix."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres du gestionnaire de temps de recharge, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de sorts sur chaque barre d'info, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des points de combo sur la barre d'info de votre cible, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des points de combo, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres des compteurs de dégâts, de soins et de menace, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre d'expérience et de réputation, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de vie sur chaque barre d'info, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de vie sous l'infobulle d'une unité, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres de vie des familiers, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres de ressource des familiers, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres de progression du suivi et de la fenêtre contextuelle, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres de vie des cases de raid, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide des barres de ressource des cases de raid, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide du rythme de frappe, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de vie de ce cadre, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de ressource de ce cadre, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de votre barre de sorts, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de sorts de votre focalisation, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "La partie vide de la barre de sorts de votre cible, derrière le remplissage. Général utilise le fond de barre de Général > Apparence."
L["The empty part's color when Missing health color is Custom color."] = "La couleur de la partie vide lorsque Couleur de vie manquante est réglée sur Couleur personnalisée."
L["The experience bar on top of the panel, or reputation at the level cap."] = "La barre d'expérience en haut du panneau, ou la réputation au niveau maximum."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "Le texte de la barre d'expérience et son +PX. Général utilise la police de Général > Apparence."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "La barre d'expérience, le compteur de dégâts et la minicarte s'estompent ensemble (ainsi que la fenêtre séparée du compteur, si elle est utilisée)."
L["The faction's name on the bar."] = "Le nom de la faction sur la barre."
L["The fifth chat channel you joined, often a custom one."] = "Le cinquième canal de discussion que vous avez rejoint, souvent un canal personnalisé."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "Le cinquième point se remplit avec la Couleur pleine (rouge au départ), pour qu'une rangée complète se remarque d'un coup d'œil."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "Le remplissage de toutes les barres : vie, ressource, barres de sorts, minuteurs de frappe, expérience, compteur de dégâts, barres d'info et plus encore, sauf si la page propre d'un cadre en choisit une autre. Les textures partagées par d'autres addons (SharedMedia) sont listées après les nôtres."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres du gestionnaire de temps de recharge. Général utilise la texture de barre de Général > Apparence."
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "Le remplissage des barres des fenêtres DaylightUI : réputation, compétences, métiers, expérience du familier, objectifs de quête. Elles gardent leur forme arrondie. Général utilise la texture de barre ci-dessus."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de sorts sur chaque barre d'info. Général utilise la texture de barre de Général > Apparence."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "Le remplissage des points de combo sur la barre d'info de votre cible. Général utilise la texture de barre de Général > Apparence."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "Le remplissage des points de combo. Général utilise la texture de barre de Général > Apparence."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres des compteurs de dégâts, de soins et de menace. Général utilise la texture de barre de Général > Apparence."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre d'expérience et de réputation. Général utilise la texture de barre de Général > Apparence."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de vie sur chaque barre d'info. Général utilise la texture de barre de Général > Apparence."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de vie sous l'infobulle d'une unité. Général utilise la texture de barre de Général > Apparence."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres de vie des familiers. Général utilise la texture de barre de Général > Apparence."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres de ressource des familiers. Général utilise la texture de barre de Général > Apparence."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "Le remplissage des barres de progression du suivi et de la fenêtre contextuelle. Général utilise la texture de barre de Général > Apparence."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres de vie des cases de raid. Général utilise la texture de barre de Général > Apparence."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "Le remplissage des barres de ressource des cases de raid. Général utilise la texture de barre de Général > Apparence."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "Le remplissage du rythme de frappe. Général utilise la texture de barre de Général > Apparence."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de vie de ce cadre. Général utilise la texture de barre de Général > Apparence."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de ressource de ce cadre. Général utilise la texture de barre de Général > Apparence."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "Le remplissage de votre barre de sorts. Général utilise la texture de barre de Général > Apparence."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de sorts de votre focalisation. Général utilise la texture de barre de Général > Apparence."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "Le remplissage de la barre de sorts de votre cible. Général utilise la texture de barre de Général > Apparence."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "La police ci-dessus s'applique partout à la fois, sauf si la page propre d'un cadre ou la police de fenêtre ci-dessous en choisit une autre. Ceci remet toutes ces exceptions sur la police ci-dessus."
L["The friendly health bar's color when Bar color is One color."] = "La couleur de la barre de vie alliée lorsque Couleur de la barre est réglée sur Une couleur."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar. Also the game's own character and inspect windows while Daylight UI's are off."] = "Le menu du jeu, la liste des addons, les macros, l'horloge, le butin, le sertissage, l'amélioration d'objets, le recycleur, l'hôtel des ventes, le livre des métiers, le cadre de la carte du monde, la barre de respiration. Aussi les fenêtres de personnage et d'inspection du jeu tant que celles de Daylight UI sont désactivées."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "Le menu du jeu, la liste des addons, les macros, l'horloge, le butin, le sertissage, l'amélioration, le recycleur, l'hôtel des ventes, le cadre de la carte du monde, la barre de respiration."
L["The game only reports range for your group; anyone else stays at full opacity."] = "Le jeu ne fournit la portée que pour votre groupe ; les autres restent à pleine opacité."
L["The game shows it as a bar."] = "Le jeu l'affiche sous forme de barre."
L["The game shows it as an icon."] = "Le jeu l'affiche sous forme d'icône."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "La discussion du jeu avec l'apparence DaylightUI, dans le coin inférieur gauche. La discussion fonctionne normalement."
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "Les conseils du jeu pour les nouveaux joueurs (le réglage « Tutoriels » du jeu). Désactivé, ils sont coupés."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "Les nombres du jeu qui jaillissent de ce que vous frappez, et le texte de combat défilant au-dessus de vous."
L["The game's own"] = "Celui du jeu"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "Les cadres d'amélioration du jeu s'affichent à côté des barres de DaylightUI. Désactivé, nos barres les remplacent (ils restent affichés tant que le Mode Édition est ouvert)."
L["The game's own messages: logins, /played, errors and the like."] = "Les messages propres au jeu : connexions, /played, erreurs et autres."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "Réglage propre au jeu : une quête acceptée est directement ajoutée au suivi."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "Réglage propre au jeu : la carte tourne avec vous, la direction où vous regardez est donc toujours en haut. Désactivé, le nord est toujours en haut."
L["The game's own settings for how the numbers leave the target."] = "Les réglages propres au jeu sur la façon dont les nombres quittent la cible."
L["The game's own switches."] = "Les options propres au jeu."
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "Les fenêtres du jeu au style DaylightUI : fond du panneau d'information, bordures DaylightUI, police, contrôles et barres de défilement."
L["The game's own windows in the DaylightUI look."] = "Les fenêtres du jeu avec l'apparence DaylightUI."
L["The game's quest tracker, placed under the panel."] = "Le suivi des quêtes du jeu, placé sous le panneau."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "Le texte défilant du jeu au-dessus de votre personnage : coups reçus, soins, déclenchements et plus encore."
L["The game's tooltips in the DaylightUI look."] = "Les infobulles du jeu avec l'apparence DaylightUI."
L["The game's tooltips."] = "Les infobulles du jeu."
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "Les fenêtres du jeu que Daylight UI n'a pas refaites. Les fenêtres refaites ont leurs propres interrupteurs dans Extras."
L["The gap between buff icons."] = "L'écart entre les icônes d'amélioration."
L["The gap between combo point pips."] = "L'écart entre les points de combo."
L["The gap between combo points."] = "L'écart entre les points de combo."
L["The gap between debuff icons."] = "L'écart entre les icônes d'affaiblissement."
L["The gap between icons."] = "L'écart entre les icônes."
L["The gap between lines, when there's more than one."] = "L'écart entre les lignes, lorsqu'il y en a plusieurs."
L["The gap between one party frame and the next."] = "L'écart entre un cadre de groupe et le suivant."
L["The gap between this bar's buttons."] = "L'écart entre les boutons de cette barre."
L["The gap between this bar's icons."] = "L'écart entre les icônes de cette barre."
L["The glow behind your character in this color."] = "La lueur derrière votre personnage, dans cette couleur."
L["The glowing border on a button when its spell procs."] = "La bordure lumineuse sur un bouton lorsque son sort se déclenche."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "L'or en bas du sac défile jusqu'à son nouveau montant. Nécessite les Effets de mouvement (Général > Apparence)."
L["The green numbers over who you heal."] = "Les nombres verts au-dessus de ceux que vous soignez."
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "Le guide qui a configuré ce personnage : une configuration rapide, une visite de tout ce que fait DaylightUI, ou un autre profil."
L["The guide window (old and new), its steps and its item and target boxes."] = "La fenêtre du guide (ancienne et nouvelle), ses étapes et ses cadres d'objet et de cible."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "L'aiguille et le temps sur chaque barre. Attaché sous la barre de sorts, il reste assez petit pour la barre."
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "Les chiffres de vie et de niveau sur les barres d'info. « Général » utilise la police de Général > Apparence."
L["The health bar fills bottom to top instead of across."] = "La barre de vie se remplit de bas en haut au lieu de la gauche vers la droite."
L["The health bar fills from the opposite side."] = "La barre de vie se remplit depuis le côté opposé."
L["The health bar's color for a dead unit."] = "La couleur de la barre de vie d'une unité morte."
L["The health bar's color for a friendly NPC."] = "La couleur de la barre de vie d'un PNJ amical."
L["The health bar's color for a player who went offline."] = "La couleur de la barre de vie d'un joueur déconnecté."
L["The health bar's color for an NPC someone else tagged first."] = "La couleur de la barre de vie d'un PNJ engagé en premier par quelqu'un d'autre."
L["The health bar's color for an NPC that attacks you."] = "La couleur de la barre de vie d'un PNJ qui vous attaque."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "La couleur de la barre de vie d'un PNJ qui vous ignore tant que vous ne le frappez pas."
L["The health bar's color when Health bar color is One color."] = "La couleur de la barre de vie quand « Couleur de la barre de vie » est sur « Une couleur »."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "Le texte de vie s'affiche aussi quand la vie est pleine. Désactivé, il disparaît tant que l'unité a toute sa vie."
L["The health text's color when Health text color is Custom."] = "La couleur du texte de vie quand « Couleur du texte de vie » est sur « Personnalisée »."
L["The highest rank"] = "Le rang le plus élevé"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "La couleur de surbrillance : le ton discret de Daylight, le dégradé Daylight, la couleur de votre classe ou son dégradé (page Dégradés), ou une couleur de votre choix."
L["The highlight's color when Active spell is set to Your own color."] = "La couleur de surbrillance quand « Sort actif » est sur « Votre propre couleur »."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "L'icône de la quête vers laquelle pointe la flèche de la minicarte (cliquez sur l'icône d'une quête pour la choisir), et la lueur derrière une icône survolée."
L["The info panel, meter, map and tracker."] = "Le panneau d'infos, le compteur, la carte et le suivi."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "Le niveau d'objet en bas dans la couleur de qualité de votre équipement, la durabilité du vert au jaune puis au rouge. Désactivé, les deux sont en gris uni."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "Le niveau d'objet des armes et armures en banque, dans le coin inférieur gauche."
L["The item level of weapons and armor in the bottom left corner."] = "Le niveau d'objet des armes et armures dans le coin inférieur gauche."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "Les kobolds de la mine portent des bougies sur la tête pour voir dans le noir. Rapportez-m'en huit et vous ne le regretterez pas."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "Les outils de chef sont désactivés : Cadres d'unité > Raid > Outils de chef."
L["The leader tools open after the fight."] = "Les outils de chef s'ouvriront après le combat."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "Les outils de chef se placent à côté des cadres de groupe ou de raid de Daylight UI, qui sont désactivés."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "La couronne du chef reste affichée en combat. Désactivé, elle se masque pendant que vous combattez."
L["The level in front of each quest name."] = "Le niveau devant le nom de chaque quête."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "La ligne sous l'onglet ouvert en haut (Personnage, Réputation, Compétences...)."
L["The line under the open tab in this color."] = "La ligne sous l'onglet ouvert dans cette couleur."
L["The line where the range starts. 0 hides it."] = "La ligne où commence la portée. 0 la masque."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "Les lignes au milieu de l'écran (interrompu, sacs pleins, nouvelle zone découverte) dans votre police, les erreurs en rouge doux, avec apparition et disparition en fondu. Déplacez-les avec /dui unlock. Désactivez pour voir le texte rouge et jaune du jeu."
L["The lines under the headers in this color."] = "Les lignes sous les en-têtes dans cette couleur."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "La liste s'étend vers le haut depuis sa poignée au lieu du bas. Pour un suivi placé bas sur l'écran."
L["The look everything shares: the font, the accent color and the window background."] = "L'apparence commune à tout : la police, la couleur d'accent et le fond des fenêtres."
L["The look shared by everything DaylightUI draws."] = "L'apparence commune à tout ce que dessine DaylightUI."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "La fenêtre du navigateur de butin, ses listes, boutons et dialogues ; ses icônes et cartes sont conservées."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "La position de la fenêtre de butin est gérée par le Mode Édition du jeu, et vous utilisez votre propre disposition du Mode Édition : déplacez-la là-bas (Échap > Mode Édition)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "Les rangs inférieurs de chaque sort se placent sous le plus élevé, pour lancer un ancien rang pour moins de mana. Désactivé, le grimoire n'affiche que le rang le plus élevé. La page du grimoire a le même interrupteur (Masquer les rangs)."
L["The main hand bar's color."] = "La couleur de la barre de main droite."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "La marque indique ce que la quête attend, comme sur la carte : une épée pour tuer, un sac pour ramasser, un engrenage pour utiliser, un œil pour explorer, dans la couleur de la quête. Nécessite le module Quêtes ; sans lui, le !."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "Le marqueur et la flèche s'estompent pendant le combat, pour ne jamais gêner."
L["The marker in the world that leads you to your quest."] = "Le marqueur dans le monde qui vous guide vers votre quête."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "Le marqueur au-dessus de l'emplacement de la quête choisie (cliquez sur son icône dans le suivi), au style DaylightUI, avec la distance. Il s'estompe une fois dans la zone de la quête sur la carte. Désactivez pour voir le marqueur du jeu."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "La couleur des barres de mêlée pendant que Frappe héroïque, Enchaînement ou Mutiler attend votre prochain coup."
L["The meter hides while you play solo."] = "Le compteur se masque quand vous jouez seul."
L["The most buff icons at once."] = "Le nombre maximal d'icônes d'amélioration à la fois."
L["The most buffs you can purge or steal one plate shows."] = "Le nombre maximal d'améliorations dissipables ou volables affichées par barre."
L["The most debuff icons at once."] = "Le nombre maximal d'icônes d'affaiblissement à la fois."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "Le nombre maximal d'affaiblissements des autres joueurs, affichés après les vôtres. Uniquement avec « Les miens d'abord, puis les autres »."
L["The most group members the threat meter lists at once, under the damage meter."] = "Le nombre maximal de membres du groupe listés à la fois par le compteur de menace, sous le compteur de dégâts."
L["The most group members the threat meter lists at once."] = "Le nombre maximal de membres du groupe listés à la fois par le compteur de menace."
L["The most icons this group shows at once."] = "Le nombre maximal d'icônes affichées à la fois par ce groupe."
L["The most of your buffs one friendly plate shows."] = "Le nombre maximal de vos améliorations affichées sur une barre alliée."
L["The most of your debuffs one plate shows."] = "Le nombre maximal de vos affaiblissements affichés sur une barre."
L["The most of your own debuffs shown at once."] = "Le nombre maximal de vos propres affaiblissements affichés à la fois."
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "La couleur de la bordure de survol quand « Couleur de la bordure de survol » est sur « Votre propre couleur »."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "Le nom flotte au-dessus de la barre, à son extrémité extérieure. Les noms longs sont tronqués."
L["The name of a buff or debuff as it lands on you."] = "Le nom d'une amélioration ou d'un affaiblissement quand il vous atteint."
L["The name sits in a small tab above the frame. Long names are cut short."] = "Le nom se place dans un petit onglet au-dessus du cadre. Les noms longs sont tronqués."
L["The name's color when Name color is Custom."] = "La couleur du nom quand « Couleur du nom » est sur « Personnalisée »."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "Les noms sur tous les cadres d'unité, sauf si un cadre choisit les siens. Classe et réaction : les joueurs selon la couleur de classe, les autres selon amical, neutre ou hostile."
L["The names' color when Name color is Custom."] = "La couleur des noms quand « Couleur du nom » est sur « Personnalisée »."
L["The newest first. Click one to move it again."] = "Les plus récents d'abord. Cliquez sur l'un d'eux pour le déplacer à nouveau."
L["The note box shows after the fight."] = "La zone de note s'affichera après le combat."
L["The number on an icon showing how many stacks it has."] = "Le chiffre sur une icône indiquant son nombre de cumuls."
L["The numbers change color for the last seconds of the cooldown."] = "Les chiffres changent de couleur pendant les dernières secondes du temps de recharge."
L["The numbers in objectives, like 3/8."] = "Les chiffres des objectifs, comme 3/8."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "Les chiffres sur la barre, par ex. 1 200 / 5 000 (+800), où +800 est votre expérience de repos."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "Les chiffres sur la barre, par ex. 1 800 / 3 000."
L["The numbers over what you hit."] = "Les chiffres au-dessus de ce que vous frappez."
L["The off hand bar's color."] = "La couleur de la barre de main gauche."
L["The order of the quests inside each zone in the quest log on the map."] = "L'ordre des quêtes dans chaque zone du journal des quêtes sur la carte."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "La forme selon laquelle chaque bouton est découpé. L'icône, la bordure et l'ombre du temps de recharge la suivent."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "Le contour ou la lueur dans votre couleur d'accent (Apparence), qui suit ses changements. Désactivé, utilise les couleurs ci-dessous."
L["The outline's color when Target outline color is Custom color."] = "La couleur du contour quand « Couleur du contour de la cible » est sur « Couleur personnalisée »."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "Le panneau derrière la discussion, avec sa bordure. Désactivé, seul le texte de discussion s'affiche."
L["The panel's framed box behind the list, as tall as what's shown."] = "Le cadre du panneau derrière la liste, aussi haut que son contenu."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "La barre de vie du familier prend à la place la couleur de son humeur : rouge mécontent, jaune satisfait, vert heureux. Désactivez le carré pour n'avoir que ceci."
L["The pets' health text. General uses the font on General > Appearance."] = "Le texte de vie des familiers. « Général » utilise la police de Général > Apparence."
L["The pets' names. General uses the font on General > Appearance."] = "Les noms des familiers. « Général » utilise la police de Général > Apparence."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "La portion de barre que vous venez de gagner clignote et « +PX » s'élève ; un balayage lors d'un passage de niveau. Nécessite les effets de mouvement (Général > Apparence)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "Les points s'élargissent pour couvrir tout le cadre, la rangée se lit alors comme une barre."
L["The pips' color with One color, or the color they start from with Color to full color."] = "La couleur des points avec « Une couleur », ou leur couleur de départ avec « Couleur vers couleur pleine »."
L["The players who keep DaylightUI going. Thank you."] = "Les joueurs qui font vivre DaylightUI. Merci."
L["The power bar's color when Power bar color is One color."] = "La couleur de la barre de ressource quand « Couleur de la barre de ressource » est sur « Une couleur »."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "Le texte de ressource s'affiche aussi quand la mana, la rage ou l'énergie est pleine. Désactivé, il disparaît quand elle est pleine."
L["The pressed border's color when Pressed border color is set to Your own color."] = "La couleur de la bordure d'appui quand « Couleur de la bordure d'appui » est sur « Votre propre couleur »."
L["The priority quest's color while Priority quest color is set to Custom."] = "La couleur de la quête prioritaire quand « Couleur de la quête prioritaire » est sur « Personnalisée »."
L["The proc border's color when Proc border is set to Your own color."] = "La couleur de la bordure de déclenchement quand « Bordure de déclenchement » est sur « Votre propre couleur »."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "Le profil %s est prêt. Choisissez-le pour ce personnage (ou un jeu de talents) pour l'utiliser."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "Le profil %s : ses réglages, les positions des cadres et la disposition du Mode Édition. Ctrl+C pour copier, puis partagez-le."
L["The profile for your first talent set. Changing it asks to reload."] = "Le profil de votre premier jeu de talents. Le changer demande un rechargement."
L["The profile for your second talent set; swapping talents asks to switch."] = "Le profil de votre second jeu de talents ; changer de talents propose de basculer."
L["The profile in use as text to copy and share."] = "Le profil utilisé, sous forme de texte à copier et partager."
L["The profile is ready. Reload to use it."] = "Le profil est prêt. Rechargez pour l'utiliser."
L["The profile is used as it is; nothing in it changes."] = "Le profil est utilisé tel quel ; rien n'y est modifié."
L["The profile this character uses. Changing it asks to reload."] = "Le profil utilisé par ce personnage. Le changer demande un rechargement."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "La disposition du Mode Édition du profil sera appliquée après le rechargement (%s)."
L["The progress bars' color while Progress bar color is set to Custom."] = "La couleur des barres de progression quand « Couleur des barres de progression » est sur « Personnalisée »."
L["The quest log on the world map."] = "Le journal des quêtes sur la carte du monde."
L["The quest under the mouse stays bright, the others ease dimmer."] = "La quête survolée reste lumineuse, les autres s'atténuent doucement."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Les cadres de raid de 11 à 20 joueurs. Affichage, fondu, textures et polices sont sur la page Raid 10."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Les cadres de raid de 21 à 40 joueurs. Affichage, fondu, textures et polices sont sur la page Raid 10."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "Le texte de vie des tuiles de raid. « Général » utilise la police de Général > Apparence."
L["The raid tiles' names. General uses the font on General > Appearance."] = "Les noms des tuiles de raid. « Général » utilise la police de Général > Apparence."
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "La couleur de nom propre aux tuiles de raid. « Comme la page Couleurs » suit la couleur de nom commune à tous les cadres."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "La barre à distance indique l'éloignement de votre cible au lieu de son nom : Mêlée, Zone morte, 10 à 35 m, Portée max. ou Hors de portée."
L["The ranged bar's color."] = "La couleur de la barre à distance."
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "Le rouge d'un anneau, d'un onglet de nom ou d'une tuile de raid pendant que quelque chose attaque l'unité, ou une couleur de votre choix."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "La réputation que vous suivez, en permanence, sur sa propre barre. Choisissez la faction sur la page Réputation de la fenêtre du personnage. Déplacez-la en mode déverrouillage ; faites glisser son coin pour la redimensionner."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "L'anneau (ou l'onglet de nom, ou la tuile de raid) qui devient rouge pendant que quelque chose attaque l'unité ; le dragon d'un élite garde sa couleur, ses yeux s'embrasent."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "L'icône de rôle reste affichée en combat. Désactivé, elle se masque pendant que vous combattez."
L["The row above the bar that holds the name and the health number."] = "La rangée au-dessus de la barre qui contient le nom et le chiffre de vie."
L["The same click again removes it."] = "Le même clic à nouveau le retire."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "Les mêmes couleurs que dans les réglages de discussion du jeu : un changement s'applique à tous les onglets."
L["The same size as the top-right panel with its damage meter out."] = "La même taille que le panneau en haut à droite avec son compteur de dégâts sorti."
L["The search failed. Try Refresh."] = "La recherche a échoué. Essayez « Actualiser »."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "L'ombre sur la vie que vos sorts de dégâts sur la durée vont encore retirer, sur la cible et sur les barres d'info ennemies."
L["The shade that sweeps over a button while it's on cooldown."] = "L'ombre qui balaie un bouton pendant son temps de recharge."
L["The short tag before these messages. Left empty it stays [%s]."] = "L'étiquette courte devant ces messages. Laissée vide, elle reste [%s]."
L["The side the whisper tiles and conversations slide out from. Left suits a chat on the right of your screen."] = "Le côté d'où glissent les tuiles de chuchotement et les conversations. « Gauche » convient à une discussion placée à droite de l'écran."
L["The size of each whisper tile."] = "La taille de chaque tuile de chuchotement."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "La taille des symboles d'entrée, de maître de vol, de bateau et de zeppelin sur la carte du monde. Ils gardent cette taille lors du zoom."
L["The skull, star and other raid markers just left of the bar."] = "Le crâne, l'étoile et les autres marqueurs de raid juste à gauche de la barre."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "La barre de vie fine. Le nom, le chiffre de vie et la ligne de ressource se placent à l'extérieur."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "Le petit onglet sur le bord gauche du compteur (visible quand la souris est proche) le sort ou le rentre manuellement."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "Le petit onglet qui contient le nom au-dessus du cadre : sa propre bordure, ses coins, son ombre, sa position et sa largeur."
L["The small zone names over each group of quests."] = "Les petits noms de zone au-dessus de chaque groupe de quêtes."
L["The soft light behind the model on the Character page."] = "La lumière douce derrière le modèle sur la page Personnage."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "La lumière douce derrière le modèle sur la page Personnage. Désactivé, seul le fond de la fenêtre s'affiche."
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "Le son quand quelqu'un vous chuchote. Les cinq premiers sont de doux carillons conçus pour DaylightUI ; en choisir un le joue une fois."
L["The space between the health bar and the power line under it."] = "L'espace entre la barre de vie et la ligne de ressource en dessous."
L["The spell an enemy is casting, under its health bar."] = "Le sort qu'un ennemi incante, sous sa barre de vie."
L["The spell being cast, as a small icon left of the cast bar."] = "Le sort en cours d'incantation, en petite icône à gauche de la barre de sorts."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "Le nom du sort et le temps sur les barres de sorts. « Général » utilise la police de Général > Apparence."
L["The spell name and time on your cast bar."] = "Le nom du sort et le temps sur votre barre de sorts."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "Le nom du sort et le temps sur votre barre de sorts. « Général » utilise la police de Général > Apparence."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "Le nom du sort et le temps sur la barre de sorts de votre focalisation. « Général » utilise la police de Général > Apparence."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "Le nom du sort et le temps sur la barre de sorts de votre focalisation. Dans le cadre, il reste assez petit pour la barre de ressource."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "Le nom du sort et le temps sur la barre de sorts de votre cible. « Général » utilise la police de Général > Apparence."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "Le nom du sort et le temps sur la barre de sorts de votre cible. Dans le cadre, il reste assez petit pour la barre de ressource, sauf si « Taille du texte dans le cadre » est réglée."
L["The spell name and timer on the target's cast bar."] = "Le nom du sort et le minuteur sur la barre de sorts de la cible."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "Le nom du sort et le minuteur quand la barre est dans le cadre de la cible, même au-delà de la hauteur de la barre de ressource. 0 utilise « Taille du texte de la barre de sorts de la cible », gardée assez petite pour la barre de ressource."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "L'icône du sort au bout de la barre de sorts de votre focalisation. Pas quand elle est dans le cadre."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "L'icône du sort au bout de la barre de sorts de votre cible. Pas quand elle est dans le cadre."
L["The spell's name on every cast bar."] = "Le nom du sort sur toutes les barres de sorts."
L["The spell's own"] = "Celle du sort"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "La couleur propre au sort (Rénovation en vert, un bouclier en bleu), ou une couleur de votre choix."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "Les touches du grimoire et des talents ouvrent la fenêtre de DaylightUI. En combat, le grimoire du jeu s'ouvre, pour pouvoir encore glisser des sorts sur vos barres. Désactivez pour toujours utiliser la fenêtre du jeu."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "Le grimoire et les talents, les fenêtres de métiers, le livre des métiers, l'écurie."
L["The square minimap in the panel."] = "La minicarte carrée dans le panneau."
L["The square's color when Heal indicator color is Custom color."] = "La couleur du carré quand « Couleur de l'indicateur de soins » est sur « Couleur personnalisée »."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "Les en-têtes des groupes de statistiques et ceux des autres pages. « Chacun la sienne » : une couleur par groupe de statistiques, utilisées tour à tour sur les autres pages."
L["The sweep can't start in combat."] = "Le balayage ne peut pas démarrer en combat."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "La main et le temps du minuteur de coups. « Général » utilise la police de Général > Apparence."
L["The tag after a PvP quest's title."] = "L'étiquette après le titre d'une quête JcJ."
L["The tag after a dungeon quest's title."] = "L'étiquette après le titre d'une quête de donjon."
L["The tag after a raid quest's title."] = "L'étiquette après le titre d'une quête de raid."
L["The tag after an elite quest's title."] = "L'étiquette après le titre d'une quête élite."
L["The talents you're using now."] = "Les talents que vous utilisez actuellement."
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "La couleur des barres de sorts de la cible et de la focalisation pendant un instant après une interruption."
L["The target and focus cast bars' color while they cast."] = "La couleur des barres de sorts de la cible et de la focalisation pendant une incantation."
L["The target and focus cast bars' color while they channel."] = "La couleur des barres de sorts de la cible et de la focalisation pendant une canalisation."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "Les dégradés de classe et de ressource de la cible et de la cible de la cible vont dans l'autre sens, en miroir des vôtres. Uniquement pour un dégradé horizontal."
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "Le texte des fenêtres de DaylightUI (personnage, grimoire, métiers, sacs, journal des quêtes) et des fenêtres du jeu qu'il restyle. « Général » utilise la police ci-dessus."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "Les textures ci-dessus s'appliquent à toutes les barres à la fois, sauf quand la page d'un cadre ou les barres de fenêtre ci-dessous en choisissent une autre. Ceci remet toutes celles-ci sur les textures ci-dessus."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "La fine ligne sous chaque en-tête. « Comme le soulignement d'onglet » : le réglage de « Soulignement d'onglet » ci-dessous. « Dégradé de classe » utilise les couleurs de votre classe de la page Dégradés."
L["The thin power bar under the health bar."] = "La fine barre de ressource sous la barre de vie."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "La fine bande sous la minicarte avec l'or, l'équipement, la place dans les sacs, etc."
L["The threat bars' color when Bar color is One color."] = "La couleur des barres de menace quand « Couleur de la barre » est sur « Une couleur »."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "Les couleurs de menace s'éclaircissent et s'assombrissent lentement, plus vite quand un monstre est sur le point de changer de cible. Nécessite la barre de vie, la bordure ou la lueur ci-dessus."
L["The tick next to a finished objective."] = "La coche à côté d'un objectif terminé."
L["The time at the bottom of the minimap."] = "L'heure en bas de la minicarte."
L["The time before each message (the game's own setting)."] = "L'heure avant chaque message (réglage du jeu)."
L["The time left as a number on each icon."] = "Le temps restant en chiffres sur chaque icône."
L["The time left on a timed quest once it's under a minute."] = "Le temps restant d'une quête chronométrée une fois sous la minute."
L["The time left on a timed quest."] = "Le temps restant d'une quête chronométrée."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "Le temps sur toutes les barres de sorts : le temps restant, le temps restant sur la durée totale, ou rien."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "La teinte d'un bouton quand votre cible est hors de portée, si « Hors de portée » est sur « Teinter l'icône »."
L["The tooltip text; titles are a little larger."] = "Le texte des infobulles ; les titres sont un peu plus grands."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "Le panneau en haut à droite : barre d'expérience en haut, compteur de dégâts et minicarte en dessous. Déplacez-le en mode déverrouillage."
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "Les deux extrémités du dégradé de la barre. Avec « Dégradé » désactivé, la barre prend l'extrémité claire."
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "Les remplissages bicolores utilisés par les barres réglées sur un dégradé (« Dégradé de classe » sur les cadres d'unité et les barres d'info, barres de ressource)."
L["The unit you set as focus."] = "L'unité que vous avez définie comme focalisation."
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "La vie de l'unité en texte à l'extrémité droite de la barre. Choisissez le format sous « Texte de vie »."
L["The unit's health written on this frame."] = "La vie de l'unité écrite sur ce cadre."
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "Le niveau de l'unité à l'extrémité gauche de la barre, dans la couleur de difficulté du jeu ; ?? pour une unité bien au-dessus de vous, + pour un élite."
L["The whole Bank and alts window, slots, text and buttons together."] = "Toute la fenêtre Banque et rerolls : emplacements, texte et boutons ensemble."
L["The whole bag window, slots, text and buttons together."] = "Toute la fenêtre des sacs : emplacements, texte et boutons ensemble."
L["The whole bank window, slots, text and buttons together."] = "Toute la fenêtre de la banque : emplacements, texte et boutons ensemble."
L["The whole bar, icons, text and background together."] = "Toute la barre : icônes, texte et fond ensemble."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "Tout le fil. Aussi avec la molette sur sa poignée dans /dui unlock."
L["The whole group shows only during a fight."] = "Le groupe entier ne s'affiche qu'en combat."
L["The whole group shows only in a party or raid."] = "Le groupe entier ne s'affiche qu'en groupe ou en raid."
L["The whole pop-up, text and bar together."] = "Toute la fenêtre surgissante : texte et barre ensemble."
L["The width of a whisper conversation. It slides out beside the tiles, as tall as the chat."] = "La largeur d'une conversation chuchotée. Elle glisse à côté des tuiles, aussi haute que la discussion."
L["The window's title shows the player's last name after their first name."] = "Le titre de la fenêtre affiche le nom de famille du joueur après son prénom."
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "La liste et les pages de quêtes de la carte du monde au style DaylightUI, avec Suivre, Partager et Abandonner sur chaque quête. Désactivez pour utiliser celles du jeu."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "La zone ou le lieu où vous êtes, en haut de la carte (au-dessus des coordonnées)."
L["The zone or area you're in, at the top of the minimap."] = "La zone ou le lieu où vous êtes, en haut de la minicarte."
L["Their class icon"] = "Son icône de classe"
L["Their health as text at the right end of the bar."] = "Leur vie en texte à l'extrémité droite de la barre."
L["Their initial"] = "Son initiale"
L["Their initial in their class's colors, or their class icon from the set picked in Unit Frames (Daylight UI's own or a Jiberish style)."] = "Son initiale dans les couleurs de sa classe, ou son icône de classe issue du jeu choisi dans Cadres d'unité (celui de Daylight UI ou un style Jiberish)."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "Leurs raccourcis fonctionnent même masquées. Déplacez-les en mode déverrouillage."
L["Their level at the left end of the bar."] = "Leur niveau à l'extrémité gauche de la barre."
L["Their own window"] = "Leur propre fenêtre"
L["Their own window and the chat"] = "Leur propre fenêtre et la discussion"
L["Their own window: a tile beside the chat for each person you talk to; click one to open the conversation. The chat only: whispers stay in the chat like any other message."] = "Leur propre fenêtre : une tuile à côté de la discussion pour chaque personne avec qui vous parlez ; cliquez dessus pour ouvrir la conversation. La discussion uniquement : les chuchotements restent dans la discussion comme n'importe quel autre message."
L["These are for talent set %s; each talent set keeps its own."] = "Ceux-ci concernent le jeu de talents %s ; chaque jeu de talents garde les siens."
L["These talents use the profile %s. Switch to it?"] = "Ces talents utilisent le profil %s. Basculer dessus ?"
L["Thick"] = "Épais"
L["Thin"] = "Fin"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "De fines lignes divisent la barre en 20 parties, comme la barre classique : chacune vaut 5% d'un niveau."
L["This Legacy tree isn't available yet."] = "Cet arbre Héritage n'est pas encore disponible."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "La taille de nom propre à cette barre. « Taille du texte », sous « Groupe entier », règle celle de toutes les barres."
L["This character"] = "Ce personnage"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "Ce personnage n'a pas terminé le guide d'installation, les cadres déplacés reviendront donc à leur place à la déconnexion. Tapez /dui install pour le terminer."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "Ce personnage n'a pas terminé le guide d'installation, ce que vous modifiez ou déplacez sera donc perdu à la déconnexion. Terminez d'abord le guide, puis faites vos changements."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "Ceux de ce personnage, pour le jeu de talents actif. Concerne vos cadres joueur, cible, cible de la cible, familier, focalisation, groupe et raid."
L["This client has no aura container; target auras are off."] = "Ce client n'a pas de conteneur d'auras ; les auras de la cible sont désactivées."
L["This fight"] = "Ce combat"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "Le texte de vie et le grand chiffre de ce cadre. « Général » utilise la police de Général > Apparence."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "Les noms de ce cadre, et son badge de niveau. « Général » utilise la police de Général > Apparence."
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "La couleur de vie propre à ce cadre, pour qu'il se distingue des autres. « Comme la page Couleurs » suit la couleur commune à tous les cadres."
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "La couleur de nom propre à ce cadre. « Comme la page Couleurs » suit la couleur de nom commune à tous les cadres."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "Le contour, les coins et l'ombre propres à ce cadre, pour qu'il se démarque du reste de votre interface."
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "La couleur de ressource propre à ce cadre. « Comme la page Couleurs » suit la couleur commune à tous les cadres."
L["This frame's power text. General uses the font on General > Appearance."] = "Le texte de ressource de ce cadre. « Général » utilise la police de Général > Apparence."
L["This group's header. The other pages use the six colors in turn."] = "L'en-tête de ce groupe. Les autres pages utilisent les six couleurs tour à tour."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "La taille propre à cette icône. « Groupe entier », ci-dessous, règle toutes les icônes du groupe."
L["This level"] = "Ce niveau"
L["This session"] = "Cette session"
L["This set hasn't been used yet. Activate it to spend its points."] = "Ce jeu n'a pas encore été utilisé. Activez-le pour dépenser ses points."
L["This setting"] = "Ce réglage"
L["This zone"] = "Cette zone"
L["This zone only"] = "Cette zone uniquement"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "Ces erreurs discrètes jouent un tic doux et grave à la place de la réplique vocale, jamais en rafale. Suit « Sons d'interface doux » (Général > Son)."
