L["Uncommon (green) and up"] = "Inhabituel (vert) et plus"
L["Under a day"] = "Moins d'un jour"
L["Under its owner"] = "Sous son propriétaire"
L["Under the action bars"] = "Sous les barres d'actions"
L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "Sous la barre (la barre de sorts descend) ou au-dessus (le nom monte)."
L["Under the cast bar"] = "Sous la barre de sorts"
L["Under the frame (slides out)"] = "Sous le cadre (coulissant)"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "Sous le cadre, elle prolonge l'angle du cadre et coulisse quand vous incantez. Au-dessus du cadre ou indépendante, elle a sa propre taille."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "Sous le cadre, elle prolonge l'angle du cadre. Désactivé, son extrémité est droite."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "Sous le cadre, ou au-dessus, à l'écart du nom. Les améliorations ou affaiblissements de la cible de ce côté se décalent."
L["Under the meter"] = "Sous le compteur"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Sous le compteur, il surgit du bas du compteur de dégâts dans le panneau, aussi large que lui, et les lignes du compteur lui font de la place. Ancré (à gauche ou dessous), il ne s'affiche que si le compteur de dégâts est ouvert. Sa propre fenêtre se place n'importe où : déplacez-la en mode déverrouillage (/dui unlock) et faites glisser son coin pour la redimensionner."
L["Under the meter it's part of the panel, with no window of its own."] = "Sous le compteur, il fait partie du panneau, sans fenêtre propre."
L["Under the panel"] = "Sous le panneau"
L["Underline color"] = "Couleur du soulignement"
L["Undo"] = "Annuler"
L["Unexplored area brightness"] = "Luminosité des zones inexplorées"
