L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "Déverrouillé. Faites glisser pour déplacer, molette pour redimensionner, clic droit pour remettre en place, /dui lock une fois terminé."
L["Unpin"] = "Détacher"
L["Untrack"] = "Ne plus suivre"
