L["Up"] = "Haut"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "« Haut » et « Bas » font défiler le texte en ligne droite. « Arc » le projette sur le côté en le courbant vers le haut."
L["Up early. Even the murlocs are still asleep."] = "Debout tôt. Même les murlocs dorment encore."
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "Jusqu'à trois, à la taille des affaiblissements, avec un compte à rebours. Ils n'apparaissent que lorsqu'un boss les utilise. Si les cadres d'améliorations du jeu sont affichés, le jeu les y montre à la place."
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "Jusqu'à deux grandes icônes au centre, avec un balayage pour le temps restant. Elles n'apparaissent que lorsqu'un boss les utilise."
L["Up: newest at the bottom"] = "Vers le haut : les plus récents en bas"
