L["Use this font for the game's text"] = "Utiliser cette police pour le texte du jeu"
L["Use this heal indicator"] = "Utiliser cet indicateur de soins"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "Utilisée par tout le texte de DaylightUI, sauf quand la page d'un cadre choisit une autre police. « Police du jeu » est celle du client, y compris une police que vous lui avez substituée. Les polices partagées par d'autres addons (SharedMedia) sont listées après les nôtres."
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "Utilisé quand Cadres d'unité > Extras > Points de combo > Couleurs est un dégradé : « Tous les points » remplit chaque point avec une même paire, « Point 1 à 5 » donne à chaque point la sienne."
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "Utilise les cadres Raid 10, et les lignes ci-dessous sont grisées. Désactivez pour donner à cette taille de raid ses propres cadres, à partir d'une copie de Raid 10."
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "Utilise la police du jeu à la place de celles de DaylightUI, qui n'ont que des lettres latines. La fenêtre des options change après /reload."
L["Usually General."] = "Généralement Général."
L["Usually Local Defense."] = "Généralement DéfenseLocale."
L["Usually Looking for Group."] = "Généralement RechercheDeGroupe."
L["Usually Trade."] = "Généralement Commerce."
L["Usually a skill point"] = "Généralement un point de compétence"
L["Varela Round"] = "Varela Round"
L["Vendor window"] = "Fenêtre du marchand"
L["Vendors"] = "Marchands"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "Les marchands s'ouvrent aussi dans la fenêtre des PNJ, avec leurs articles sur une étagère. Désactivez pour utiliser la fenêtre de marchand du jeu."
L["Version %s."] = "Version %s."
L["Vertical (light on top)"] = "Vertical (clair en haut)"
L["Vertical bar"] = "Barre verticale"
L["View distance (yards)"] = "Distance de vue (mètres)"
L["Visibility"] = "Visibilité"
L["Visible"] = "Visible"
L["Waist"] = "Taille"
L["Wait for the talents being applied."] = "Attendez que les talents soient appliqués."
L["Walking Boots"] = "Bottes de marche"
L["Warlock"] = "Démoniste"
L["Warm bell"] = "Cloche chaleureuse"
L["Warmed by the fire"] = "Réchauffé par le feu"
L["Warns you when a mob is about to change target, or has."] = "Vous avertit quand un monstre est sur le point de changer de cible, ou l'a fait."
L["Warrior"] = "Guerrier"
L["Weapon"] = "Arme"
L["Weapon Enchant"] = "Enchantement d'arme"
L["Weapon icon"] = "Icône d'arme"
L["Weapon master"] = "Maître d'armes"
L["Weapons"] = "Armes"
L["Wearing it"] = "Porté"
L["Web addresses in messages become links; click one to copy it."] = "Les adresses web dans les messages deviennent des liens ; cliquez sur l'un d'eux pour le copier."
L["Website: %s"] = "Site web : %s"
L["Welcome"] = "Bienvenue"
L["Welcome back, %s"] = "Bon retour, %s"
L["Went out"] = "Sorti"
L["What Alt-click on a quest in the tracker does."] = "L'action d'un Alt-clic sur une quête dans le suivi."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "Le comportement d'un bouton quand votre cible est hors de portée. Le manque de mana, de rage ou d'énergie fait de même (bleu si teinté)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "L'action d'un clic sur une quête dans le suivi. Cliquer sur son icône en fait toujours votre priorité, et le clic droit ouvre son menu."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "La fonction d'un PNJ amical (Aubergiste, Maître de vol...) sous son nom, en plus petit."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "La fonction d'un PNJ (Dépeceur, Maître de vol...) sous son nom, en plus petit. Pas en instance."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "L'effet d'une barre de sorts interrompue : « Lame » la tranche en deux, « Éclats » la brise en morceaux, « Cassure » la fend en son milieu, « Consumer » brûle son remplissage, « Rembobiner » la ramène d'un coup à vide, « Onde de choc » en fait jaillir la lumière, « Pétiller » laisse sa lumière s'échapper. Vos propres interruptions s'illuminent dans votre couleur d'accent. Survolez un choix pour le voir dans l'aperçu."
L["What changed in each version."] = "Les changements de chaque version."
L["What changed in each version. Click a version to open or close it."] = "Les changements de chaque version. Cliquez sur une version pour l'ouvrir ou la fermer."
L["What each enemy plate shows on and around its bar, and its colors."] = "Ce que chaque barre ennemie affiche sur et autour de sa barre, et ses couleurs."
L["What each item's icon shows in the Bank and alts window."] = "Ce qu'affiche l'icône de chaque objet dans la fenêtre Banque et rerolls."
L["What each item's icon shows in the bank."] = "Ce qu'affiche l'icône de chaque objet dans la banque."
L["What each item's icon shows."] = "Ce qu'affiche l'icône de chaque objet."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "Ce qu'affiche chaque emplacement, de gauche à droite. L'horloge, les images par seconde et les coordonnées sont aussi sur la minicarte."
L["What fades, and when"] = "Ce qui s'estompe, et quand"
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "Ce qu'il advient de vos combats enregistrés quand vous entrez dans un donjon, un raid ou un champ de bataille : les garder, demander s'il faut réinitialiser, ou réinitialiser aussitôt. Revenir après une mort ne compte pas."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "Ce qu'il advient de vos combats enregistrés quand vous rejoignez un groupe : les garder, demander s'il faut réinitialiser, ou réinitialiser aussitôt."
L["What it shows"] = "Ce qu'il affiche"
L["What sits between the text's parts."] = "Ce qui sépare les parties du texte."
L["What the away message says."] = "Le contenu du message d'absence."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "Ce que liste le compteur : dégâts, soins, dégâts subis, interruptions, dissipations, morts, etc. Le bouton du compteur le change aussi."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "Ce que liste le second compteur : dégâts, soins, dégâts subis, interruptions, dissipations, morts, etc."
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "L'effet de la barre de sorts de la cible ou de la focalisation quand son incantation est interrompue. Vos propres interruptions s'illuminent dans votre couleur d'accent."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "Ce que fait le suivi quand vous entrez dans un donjon, un raid ou un champ de bataille. Il revient quand vous en sortez."
L["What this extra text shows first, like the name, the level or the guild."] = "Ce que ce texte supplémentaire affiche en premier, comme le nom, le niveau ou la guilde."
L["What this group takes. Click to change."] = "Ce que ce groupe accueille. Cliquez pour modifier."
L["What this slot on the data text strip shows. Slots count from the left."] = "Ce qu'affiche cet emplacement de la bande d'informations. Les emplacements se comptent depuis la gauche."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "Votre butin et vos gains de compétence, qui glissent sous forme de rubans en bas à droite."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "Votre butin glisse en bas à droite de l'écran dans la couleur de sa qualité ; les exemplaires identiques s'ajoutent à son compteur, puis il s'efface après quelques secondes. Survolez une ligne pour afficher l'infobulle de l'objet. Déplacez-le avec /dui unlock."
L["What's Training is still reading your spells."] = "What's Training lit encore vos sorts."
L["What's included"] = "Contenu"
L["What's new"] = "Nouveautés"
L["When Threat colors are on, they replace this color while showing."] = "Quand les couleurs de menace sont activées, elles remplacent cette couleur lorsqu'elles s'affichent."
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "Quand une amélioration expire, les sorts suivants glissent pour combler sa place. Si désactivé, chaque sort garde sa place. Un sort réglé sur « Garder sa place » (onglet Comportement) la garde dans tous les cas."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "Quand une incantation est interrompue, la barre reste pleine un instant et affiche « Interrompu »."
L["When a reputation goes up a standing, like Friendly to Honored, the new standing rises in at the top of the screen in its color, with the faction's name and a bar showing how far into it you are. Follows Motion effects (General > Appearance)."] = "Quand une réputation monte d'un rang, par exemple d'Amical à Honoré, le nouveau rang apparaît en haut de l'écran dans sa couleur, avec le nom de la faction et une barre indiquant votre progression. Suit les Effets de mouvement (Général > Apparence)."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "Quand un PNJ n'a qu'une seule chose à proposer (marchand, maître de vol, banquier ou maître) et aucune quête, sa fenêtre s'ouvre directement. Maintenez Maj pour voir le dialogue."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "Quand le butin automatique est activé, tout est ramassé d'un coup au lieu d'un objet à la fois."
L["When hovering a button shows its spell or item tooltip."] = "Quand le survol d'un bouton affiche l'infobulle de son sort ou de son objet."
L["When it shows"] = "Quand l'afficher"
L["When not usable"] = "Quand inutilisable"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "Si désactivé, tout affaiblissement typé (Magie, Malédiction, Maladie, Poison) s'affiche, même ceux que vous ne pouvez pas dissiper."
L["When off, the game's own bag windows are used."] = "Si désactivé, les fenêtres de sacs du jeu sont utilisées."
L["When off, the game's tracker stays where Edit Mode puts it."] = "Si désactivé, le suivi du jeu reste là où le Mode Édition le place."
L["When ready"] = "Quand prêt"
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "Quand quelqu'un écrit votre nom dans un canal de discussion, il est mis en valeur dans votre couleur d'accent et l'onglet où il arrive s'illumine."
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "Quand la couleur d'accent est un dégradé (celui de Daylight ou de votre classe), les bordures des fenêtres le suivent."
L["When the away message answers."] = "Quand le message d'absence répond."
L["When the shown bag bar fades and how far."] = "Quand la barre de sacs affichée s'estompe, et à quel point."
L["When the shown micro menu fades and how far."] = "Quand le micro-menu affiché s'estompe, et à quel point."
L["When to show"] = "Quand afficher"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "Quand vous détruisez un objet de valeur, la boîte de confirmation est remplie pour vous. Il vous reste à appuyer sur le bouton."
L["When you dodge, parry or an attack misses you."] = "Quand vous esquivez, parez ou qu'une attaque vous rate."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "Quand vous vous absentez, le monde s'assombrit, l'interface s'estompe et votre personnage pose à côté d'une carte avec votre nom, votre zone, votre PX de repos et une anecdote. Bougez, cliquez ou appuyez sur une touche pour revenir. Jamais en combat, contre un boss, en clé mythique ou en match JcJ."
L["When you have forms"] = "Si vous avez des formes"
L["When you have totems"] = "Si vous avez des totems"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "Quand votre prochaine attaque automatique touche : une barre pour chaque main avec laquelle vous frappez."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "Où « Interrompu par » et le nom s'affichent : à côté de la barre de sorts ou en dessous."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "Où la rangée commence le long du cadre : l'extrémité biseautée tournée vers le centre de l'écran, le milieu ou l'extrémité opposée."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "Où se place l'onglet le long du haut du cadre. Un onglet pleine largeur commence toujours à l'extrémité extérieure. Vous pouvez aussi faire glisser l'onglet en mode Conception."
L["Where along the power bar the power text sits."] = "Où se place le texte de ressource le long de la barre de ressource."
L["Where new lines come in."] = "Où arrivent les nouvelles lignes."
L["Where on the button its key shows."] = "Où s'affiche le raccourci sur le bouton."
L["Where on the frame this square sits."] = "Où se place ce carré sur le cadre."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "Où apparaît la zone de saisie. « Sous le panneau » lui réserve une bande sous la discussion, pour qu'elle ne masque jamais de texte."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "Où apparaît la zone de saisie. « Sous le panneau » lui réserve une bande sous la discussion, pour qu'elle ne masque jamais de texte. « En bas », la zone de discussion Daylight remonte ses messages au-dessus de la zone de saisie pendant que vous tapez."
L["Where the dispel icon sits on each frame, or just outside it."] = "Où se place l'icône de dissipation sur chaque cadre, ou juste à l'extérieur."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "Où s'affiche le nom de l'interrupteur : à droite de la barre de sorts ou en dessous."
L["Where the leader crown sits on each frame, or just outside it."] = "Où se place la couronne de chef sur chaque cadre, ou juste à l'extérieur."
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "Où se place le nom sur la barre, lorsqu'il est dessus : à gauche, au centre ou à droite."
L["Where the name sits across the bar: left, center or right."] = "Où se place le nom sur la barre : à gauche, au centre ou à droite."
L["Where the name sits inside its tab: left, center or right."] = "Où se place le nom dans son onglet : à gauche, au centre ou à droite."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "Où s'ouvrent les chiffres quand vous survolez la barre. « Automatique » les ouvre vers le centre de l'écran."
L["Where the raid marker sits on each frame, or just outside it."] = "Où se place le marqueur de raid sur chaque cadre, ou juste à l'extérieur."
L["Where the ready check answer sits on each frame, or just outside it."] = "Où se place la réponse à l'appel sur chaque cadre, ou juste à l'extérieur."
L["Where the role icon sits on each frame, or just outside it."] = "Où se place l'icône de rôle sur chaque cadre, ou juste à l'extérieur."
L["Where the role, marker, crown and dispel icons sit on a tile."] = "Où se placent les icônes de rôle, de marqueur, de couronne et de dissipation sur une tuile."
L["Where things sit on your screen."] = "Où se placent les éléments à l'écran."
L["Where this category sits on the bar."] = "Où se place cette catégorie sur la barre."
L["Where this extra text sits on the frame, or just outside it."] = "Où se place ce texte supplémentaire sur le cadre, ou juste à l'extérieur."
L["Where this group sits in the bag."] = "Où se place ce groupe dans le sac."
L["Where to start"] = "Par où commencer"
L["Where you put it"] = "Là où vous le placez"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "Où se placent vos cadres. Les soigneurs ont le groupe en grandes tuiles au centre de l'écran."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "Si chaque groupe de raid forme une colonne, côte à côte, ou une rangée, empilées vers le bas."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "Si le compteur mesure le combat en cours ou tous les combats depuis la dernière réinitialisation."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "Si l'extrémité de l'onglet de nom est biseautée. « Comme le cadre » suit l'extrémité du cadre."
L["Whether the party frames stack down or line up across."] = "Si les cadres de groupe s'empilent vers le bas ou s'alignent horizontalement."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "Si le second compteur mesure le combat en cours ou tous les combats depuis la dernière réinitialisation."
L["Whether this extra group shows debuffs or buffs."] = "Si ce groupe supplémentaire affiche des affaiblissements ou des améliorations."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "Si vos barres et votre cadre s'effacent hors combat. Chaque élément a ensuite son propre réglage de visibilité."
L["Which bar the rows below set."] = "La barre que règlent les lignes ci-dessous."
L["Which buffs show."] = "Les améliorations affichées."
L["Which buffs this group shows."] = "Les améliorations affichées par ce groupe."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "Les boutons que modifient les réglages d'apparence de cette page. Une barre conserve ce que vous modifiez pour elle ; le reste suit « Toutes les barres »."
L["Which corner of the button its count shows in."] = "Le coin du bouton où s'affiche son nombre."
L["Which debuffs show."] = "Les affaiblissements affichés."
L["Which debuffs this group shows."] = "Les affaiblissements affichés par ce groupe."
L["Which end of the group stays put when a spell in it hides."] = "L'extrémité du groupe qui reste fixe quand l'un de ses sorts est masqué."
L["Which frame the pips sit on."] = "Le cadre sur lequel se placent les points."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "La touche qui accepte, continue et termine. Entrée est aussi la touche qui ouvre la discussion."
L["Which numbers"] = "Quels chiffres"
L["Which of the six squares the rows below set."] = "Lequel des six carrés règlent les lignes ci-dessous."
L["Which part's fade the rows below set."] = "L'élément dont les lignes ci-dessous règlent le fondu."
L["Which quest tracker?"] = "Quel suivi de quêtes ?"
L["Which side of its owner's frame each pet bar sits on."] = "Le côté du cadre de son maître où se place chaque barre de familier."
L["Which side of the list the quest item buttons sit on."] = "Le côté de la liste où se placent les boutons d'objets de quête."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "Les groupes de caractéristiques ouverts au départ. « Selon la classe et la spécialisation » : les Attributs et celui qui compte pour vous. Les groupes que vous ouvrez ou repliez vous-même sont mémorisés pour chaque personnage."
L["Which way the color runs along a bar."] = "Le sens de la couleur le long d'une barre."
L["Which way the row adds its icons, starting from its position."] = "Le sens dans lequel la rangée ajoute ses icônes, à partir de sa position."
L["Which way the row of icons fills from its first icon."] = "Le sens dans lequel la rangée d'icônes se remplit à partir de sa première icône."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "Tant que Frappe héroïque, Enchaînement ou Mutiler attend votre prochain coup, les barres de mêlée changent de couleur et affichent son nom."
L["While it's off cooldown but you can't cast it: Overpower before a dodge, Riposte before a parry, Execute on a healthy target. Show leaves it dimmed. Hide keeps its gap: the other spells don't move."] = "Quand il n'est plus en recharge mais que vous ne pouvez pas le lancer : Fulgurance avant une esquive, Riposte avant une parade, Exécution sur une cible en bonne santé. Afficher le laisse atténué. Masquer garde sa place vide : les autres sorts ne bougent pas."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "Pendant le déplacement des cadres, les bords et les centres s'alignent sur les autres cadres. Maintenez Maj pour les déposer n'importe où."
L["While possessing"] = "Pendant une possession"
L["While swinging"] = "Pendant les coups"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "Pendant les coups : chaque barre uniquement pendant son coup, masquée entre deux coups. En combat : toutes vos barres tant que vous combattez."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "Tant que l'amélioration ou l'affaiblissement n'est pas actif, il garde sa place sous forme d'icône grisée ou de barre vide, pour que vous voyiez ce qui manque."
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "Quand le panneau est masqué, la durée pendant laquelle chaque message reste avant de s'estomper. Un nouveau message ne fait pas revenir les anciens. Survolez la discussion pour tous les revoir."
L["While you cast, the power the spell will use is shaded on your power bar."] = "Pendant que vous incantez, la ressource que le sort va consommer est ombrée sur votre barre de ressource."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "Si vous avez un arc, une arme à feu, une arbalète, une arme de jet ou une baguette."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "Quand vous avez une cible, toutes les autres barres d'info s'estompent pour la faire ressortir. Une barre qui commence une incantation redevient pleinement visible."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "Quand vous avez une cible, sa barre d'info et toutes les autres utilisent les tailles ci-dessous (relatives à Largeur, Hauteur de la barre de vie et Échelle)."
L["While you have a weapon in your off hand."] = "Si vous avez une arme en main gauche."
L["Whisper"] = "Chuchoter"
L["Whisper %s"] = "Chuchoter à %s"
L["Whisper color"] = "Couleur des chuchotements"
L["Whisper sound"] = "Son des chuchotements"
L["Whisper tiles"] = "Tuiles de chuchotement"
L["Whisper tiles show"] = "Les tuiles de chuchotement affichent"
L["Whispered"] = "Chuchoté"
L["Battle.net whispers"] = "Chuchotements Battle.net"
L["Game window skins"] = "Habillage des fenêtres du jeu"
L["More windows"] = "Autres fenêtres"
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "Grimoire, inspection, métiers, recherche de groupe, boîte aux lettres, social et Héritage : l'interrupteur de chaque fenêtre, sa taille et ses extras."
L["Whispers"] = "Chuchotements"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "Les chuchotements font partie de la zone de discussion Daylight : /dui chat daylight pour l'utiliser."
L["Whispers button"] = "Bouton des chuchotements"
L["Whispers from your Battle.net friends, and yours to them."] = "Les chuchotements de vos amis Battle.net, et les vôtres envers eux."
L["Whispers in their own tab"] = "Chuchotements dans leur propre onglet"
L["Whispers open on the"] = "Les chuchotements s'ouvrent du côté"
L["Whispers show in"] = "Les chuchotements s'affichent dans"
L["Whispers you get and send."] = "Les chuchotements que vous recevez et envoyez."
L["White"] = "Blanc"
L["White, the unit's class color, or one you pick."] = "Blanc, la couleur de classe de l'unité ou une couleur de votre choix."
L["Who"] = "Qui"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "Qui un joueur ou une créature cible, dans sa couleur (« >> Vous << » quand c'est vous)."
L["Who interrupted position"] = "Position de l'interrupteur"
L["Who to whisper?"] = "À qui chuchoter ?"
L["Who your target is looking at."] = "Ce que regarde votre cible."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "Qui est le plus près de reprendre l'aggro de votre cible, dans une petite fenêtre qui glisse depuis le bord gauche du compteur de dégâts, le long de son bas, ou n'importe où de façon indépendante."
L["Whole bar"] = "Barre entière"
L["Whole group"] = "Groupe entier"
L["Whole row in full color at max points"] = "Rangée entière en couleur pleine au maximum de points"
L["Width"] = "Largeur"
L["William Pestle"] = "William Pestle"
L["Window"] = "Fenêtre"
L["Window background opacity"] = "Opacité du fond des fenêtres"
L["Window bar background"] = "Fond des barres de la fenêtre"
L["Window bar texture"] = "Texture des barres de la fenêtre"
L["Window border"] = "Bordure de la fenêtre"
L["Window font"] = "Police de la fenêtre"
L["Window height"] = "Hauteur de la fenêtre"
L["Window scale"] = "Échelle de la fenêtre"
L["Window: talking opens a window at the side. Immersive: the talk is a card on the right, the camera comes in over your shoulder and the rest of the UI fades away until you're done. Vendors and trainers stay a window."] = "Fenêtre : parler ouvre une fenêtre sur le côté. Immersif : le dialogue est une carte à droite, la caméra se place par-dessus votre épaule et le reste de l'interface s'estompe jusqu'à la fin. Les marchands et les maîtres restent une fenêtre."
L["Windows"] = "Fenêtres"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "Les fenêtres glissent à l'ouverture et à la fermeture, les infobulles apparaissent en fondu, l'icône d'un sort ressort quand il est prêt, l'or et les PX défilent. Si désactivé, tout se met en place instantanément."
L["Windows open & close"] = "Ouverture et fermeture des fenêtres"
L["Wisdom"] = "Sagesse"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "Avec « Garder sa place » (amélioration manquante), il ne s'affiche que lorsque vous devez le lancer, comme Cri de guerre."
L["With Show under Buff missing, Hide makes it appear only when you need to cast it, like Battle Shout."] = "Avec Afficher sous Amélioration manquante, Masquer ne le fait apparaître que lorsque vous devez le lancer, comme Cri de guerre."
L["With a fishing pole equipped, a quick right-click on the world casts Fishing. With no bait on the pole, the first click puts on the best bait in your bags. Holding the button still turns the camera, and clicking an NPC, an object or the bobber works as usual. Hold Shift, Ctrl or Alt to skip the cast."] = "Avec une canne à pêche équipée, un clic droit rapide sur le monde lance Pêche. S'il n'y a pas d'appât sur la canne, le premier clic pose le meilleur appât de vos sacs. Maintenir le bouton fait toujours tourner la caméra, et cliquer sur un PNJ, un objet ou le flotteur fonctionne comme d'habitude. Maintenez Maj, Ctrl ou Alt pour ne pas lancer."
L["With a pet"] = "Avec un familier"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "Si les deux sont activés, il ne s'affiche qu'en groupe et en combat. Le second compteur suit aussi ces réglages."
L["With chat open, Shift-click links the quest first."] = "Si la discussion est ouverte, Maj-clic insère d'abord un lien vers la quête."
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "Avec les objets rangés par catégories, les piles d'un même objet s'affichent en une seule, avec le total. Elles s'affichent séparément pendant un échange ou quand la boîte aux lettres ou l'hôtel des ventes est ouvert, pour que vous puissiez en diviser une par Maj-clic."
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "Avec les objets rangés par catégories, vos fragments d'âme s'affichent en un seul, avec leur nombre, même si chacun occupe toujours son propre emplacement."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "Sans portrait ni onglet de nom, les icônes de rôle, de marqueur, de couronne et de dissipation se placent dans les coins du cadre."
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "Avec la saisie en bas de la discussion : pendant que vous tapez, les messages glissent vers le haut et la zone de saisie se place en dessous, pour qu'elle ne masque jamais une ligne."
L["With the immersive look, the NPC's words appear letter by letter and the choices drift in after them. Click or press the accept key to see them all at once."] = "Avec l'aspect immersif, les paroles du PNJ apparaissent lettre par lettre et les choix arrivent ensuite. Cliquez ou appuyez sur la touche d'acceptation pour tout voir d'un coup."
L["With the immersive look, the camera comes in over your shoulder and looks at the NPC while you talk, then goes back to how you had it. Not while mounted or in a fight."] = "Avec l'aspect immersif, la caméra se place par-dessus votre épaule et regarde le PNJ pendant le dialogue, puis revient comme avant. Pas sur une monture ni en combat."
L["With the immersive look, the whole UI fades away while you talk, so only the NPC and the talk are left. A fight brings everything back at once."] = "Avec l'aspect immersif, toute l'interface s'estompe pendant le dialogue : il ne reste que le PNJ et ses paroles. Un combat ramène tout immédiatement."
L["Withdraw"] = "Retirer"
L["Withdraw gold"] = "Retirer de l'or"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Au sein de chaque zone. « Progrès le plus récent » fait remonter une quête quand une victime, un objet ou un objectif compte. « La plus proche d'abord » réévalue toutes les quelques secondes pendant vos déplacements, jamais en combat ni en donjon. Rien ne bouge en combat."
L["Wood pop"] = "Claquement de bois"
L["Words to light up"] = "Mots à mettre en valeur"
L["Words to light up, separated by commas"] = "Mots à mettre en valeur, séparés par des virgules"
L["World"] = "Monde"
L["World map"] = "Carte du monde"
L["World markers"] = "Marqueurs au sol"
L["World of Warcraft"] = "World of Warcraft"
L["Wowhead link"] = "Lien Wowhead"
L["Wowhead link (Ctrl+C copies it):"] = "Lien Wowhead (Ctrl+C pour le copier) :"
L["Wrists"] = "Poignets"
L["Write a letter..."] = "Écrire une lettre..."
L["Write a note to list for %s."] = "Écrivez une note pour l'inscription à %s."
L["Write a subject."] = "Indiquez un objet."
L["Write the full name: first and last."] = "Indiquez le nom complet : prénom et nom."
L["Writes zone names in capital letters. When off, they're written as the game writes them."] = "Écrit les noms de zones en majuscules. Désactivé, ils sont écrits comme dans le jeu."
L["XP"] = "PX"
L["XP bar"] = "Barre d'expérience"
L["XP bar position"] = "Position de la barre d'expérience"
L["XP bar, damage meter and a square minimap in one corner panel."] = "Barre d'expérience, compteur de dégâts et minicarte carrée dans un seul panneau d'angle."
L["XP gain effects"] = "Effets de gain de PX"
L["XP, reputation and skills"] = "PX, réputation et compétences"
L["Yards under the arrow"] = "Mètres sous la flèche"
L["Yell"] = "Crier"
L["Yell color"] = "Couleur des cris"
L["Yes"] = "Oui"
L["You"] = "Vous"
L["You block about 1 in %d attacks with your shield."] = "Vous bloquez environ 1 attaque sur %d avec votre bouclier."
L["You can also drag the chat's bottom-right corner to size it."] = "Vous pouvez aussi faire glisser le coin inférieur droit de la discussion pour la redimensionner."
L["You can also switch with the button next to its search box."] = "Vous pouvez aussi basculer avec le bouton à côté de son champ de recherche."
L["You can also switch with the button next to the bank's search box."] = "Vous pouvez aussi basculer avec le bouton à côté du champ de recherche de la banque."
L["You can also switch with the button next to the search box."] = "Vous pouvez aussi basculer avec le bouton à côté du champ de recherche."
L["You can make %d"] = "Vous pouvez en fabriquer %d"
L["You can reach rank %d this week"] = "Vous pouvez atteindre le rang %d cette semaine"
L["You can track up to %d quests."] = "Vous pouvez suivre jusqu'à %d quêtes."
L["You can't parry yet."] = "Vous ne pouvez pas encore parer."
L["You carry %s."] = "Vous portez %s."
L["You choose one of these:"] = "Vous choisissez l'une de ces récompenses :"
L["You dodge about 1 in %d attacks."] = "Vous esquivez environ 1 attaque sur %d."
L["You don't block yet."] = "Vous ne bloquez pas encore."
L["You don't dodge attacks yet."] = "Vous n'esquivez pas encore d'attaques."
L["You don't have that much gold."] = "Vous n'avez pas autant d'or."
L["You get back %.0f mana every 5 seconds while not casting."] = "Vous récupérez %.0f points de mana toutes les 5 secondes quand vous n'incantez pas."
L["You keep"] = "Vous conservez"
L["You parry about 1 in %d attacks from the front."] = "Vous parez environ 1 attaque frontale sur %d."
L["You shoot every %.2f seconds. Lower is faster."] = "Vous tirez toutes les %.2f secondes. Plus c'est bas, plus c'est rapide."
L["You'll also get:"] = "Vous recevrez aussi :"
L["You'll choose one of these:"] = "Vous choisirez l'une de ces récompenses :"
L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "Vous êtes en groupe : les outils de chef agissent pour de vrai. Quittez le groupe pour vous entraîner avec des membres fictifs."
L["You're in combat; this finishes as soon as it ends."] = "Vous êtes en combat ; cela se terminera dès qu'il sera fini."
L["You're not in a guild."] = "Vous n'êtes pas dans une guilde."
L["You're not in a raid."] = "Vous n'êtes pas dans un raid."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "Vous avez déjà appris des talents absents de ce build. Un maître peut les réinitialiser."
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "Vos points d'héritage, leurs récompenses, les défis qui les rapportent et les arbres d'héritage, dans une seule fenêtre, au style DaylightUI."
L["Your accent, when the accent color is set to Custom color."] = "Votre accent, quand la couleur d'accent est réglée sur « Couleur personnalisée »."
L["Your action bars and their buttons."] = "Vos barres d'actions et leurs boutons."
L["Your attacks don't land critical hits yet."] = "Vos attaques n'infligent pas encore de coups critiques."
L["Your attacks and spells miss %.1f%% less often."] = "Vos attaques et sorts ratent %.1f%% moins souvent."
L["Your bags are full."] = "Vos sacs sont pleins."
L["Your bank and your other characters' bags, from anywhere."] = "Votre banque et les sacs de vos autres personnages, depuis n'importe où."
L["Your bank from anywhere, and your other characters' bags and banks."] = "Votre banque depuis n'importe où, ainsi que les sacs et banques de vos autres personnages."
L["Your bindings"] = "Vos raccourcis"
L["Your buffs"] = "Vos améliorations"
L["Your buffs and debuffs."] = "Vos améliorations et affaiblissements."
L["Your buffs grow direction"] = "Sens d'extension de vos améliorations"
L["Your buffs left / right"] = "Vos améliorations gauche / droite"
L["Your buffs position"] = "Position de vos améliorations"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "Vos améliorations triées en groupes colorés ; affaiblissements bordés selon leur type."
L["Your buffs up / down"] = "Vos améliorations haut / bas"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "Vos améliorations, la minicarte et le panneau d'informations, le suivi de quêtes et la discussion s'estompent aussi, pour ne laisser que le feu et le monde. Survolez l'un d'eux pour le voir."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "Vos améliorations, triées en catégories colorées. Clic droit sur une amélioration pour l'annuler ; Maj-clic pour la déplacer dans une autre catégorie. La barre se place à côté du panneau d'informations ; pour la déplacer, désactivez « Attacher au panneau d'informations »."
L["Your cast bar's color for a moment after your cast is interrupted."] = "La couleur de votre barre de sorts pendant un instant après l'interruption de votre incantation."
L["Your cast bar's color while you cast."] = "La couleur de votre barre de sorts pendant que vous incantez."
L["Your cast bar's color while you channel."] = "La couleur de votre barre de sorts pendant que vous canalisez."
L["Your cast bar's colors"] = "Couleurs de votre barre de sorts"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "Vos incantations et canalisations dans votre couleur de classe, ou dans le dégradé de votre classe avec un remplissage bicolore. Pas avec le dégradé Daylight."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "Votre fenêtre du personnage : équipement, modèle, caractéristiques et les autres pages. Elle s'ouvre avec C, comme toujours."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "Votre discussion revient aussi à votre prochaine connexion sur ce personnage, sous une ligne grise indiquant quand vous êtes parti."
L["Your class"] = "Votre classe"
L["Your class can heal; pick Healer if you do."] = "Votre classe peut soigner ; choisissez Soigneur si c'est votre cas."
L["Your class's pick"] = "Le choix de votre classe"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "« Le choix de votre classe » suit votre classe sur chaque personnage. Choisissez-en une pour la suivre à la place."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "Vos sorts de dégâts sur la durée : la portion de vie qu'ils vont encore retirer est ombrée plus sombre."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "Vos sorts de dégâts sur la durée : la portion de vie qu'ils vont encore retirer est ombrée plus sombre. La couleur se règle dans Cadres d'unité > Couleurs."
L["Your debuffs"] = "Vos affaiblissements"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "Vos affaiblissements, les contrôles de foule et les améliorations que vous pouvez dissiper, sur les barres d'info ennemies."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "La barre de sorts de votre focalisation se remplit depuis la droite. Pas lorsqu'elle est placée dans le cadre."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "Les incantations de votre focalisation, tant qu'elles durent. Elle utilise les couleurs de la barre de sorts de la cible."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "Couleur de vie propre à votre cadre, pour qu'il se distingue des autres. « Comme la page Couleurs » suit la couleur commune à tous les cadres ; « Dégradé Daylight » va du bleu à l'orange du logo."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange; Accent color follows your accent on General > Appearance, gradient included."] = "La couleur de vie propre à votre cadre, pour qu'il se distingue des autres. Comme la page Couleurs suit la couleur commune à tous les cadres ; Dégradé Daylight va du bleu à l'orange du logo ; Couleur d'accent suit votre accent de Général > Apparence, dégradé compris."
L["Your frames"] = "Vos cadres"
L["Your frames per second beside the clock."] = "Vos images par seconde à côté de l'horloge."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "Vos images par seconde à côté de l'horloge. Survolez-les pour voir la latence, le processeur et la mémoire des addons."
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "Vos amis, alliances récentes, demandes d'ami et le raid, dans une seule fenêtre, au style DaylightUI."
L["Your group is too big for a %d-player activity."] = "Votre groupe est trop grand pour une activité à %d joueurs."
L["Your guild's officer chat."] = "Le canal des officiers de votre guilde."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "Vos soins sur la durée et boucliers, tout ce que vous lancez, ou tous. Une classe sans soins voit tout ce qu'elle lance."
L["Your health and mana come back faster while you're not fighting or casting."] = "Vos points de vie et votre mana reviennent plus vite quand vous ne combattez pas et n'incantez pas."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "Votre vie et votre ressource juste sous votre personnage, comme l'affichage personnel de Legion à vos pieds."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "Votre barre de vie, votre ressource en dessous et, pour les voleurs et les druides, vos points de combo, juste sous votre personnage. Elle suit la caméra quand vous zoomez."
L["Your health. Each point adds about 10; you have %.0f."] = "Vos points de vie. Chaque point en ajoute environ 10 ; vous en avez %.0f."
L["Your last name after your first, at the top of the window."] = "Votre nom de famille après votre prénom, en haut de la fenêtre."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "Vos lettres, l'envoi et ce que vous avez gagné via le courrier et l'hôtel des ventes, dans une seule fenêtre, au style DaylightUI."
L["Your listing"] = "Votre annonce"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "Votre main droite frappe toutes les %.2f secondes. Plus c'est bas, plus c'est rapide."
L["Your mana, rage or energy under the health bar."] = "Votre mana, rage ou énergie sous la barre de vie."
L["Your melee attacks hit harder: Strength adds attack power."] = "Vos attaques en mêlée frappent plus fort : la Force augmente la puissance d'attaque."
L["Your own buffs and heals over time, in a row above the name."] = "Vos propres améliorations et soins sur la durée, en rangée au-dessus du nom."
L["Your own color"] = "Votre propre couleur"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "Votre propre disposition des temps de recharge : chaque sort suivi par le gestionnaire de temps de recharge, en icône ou en barre, placé où vous voulez et aimanté aux autres. Une disposition par jeu de talents, pour ce personnage."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "Votre propre cadre se place avec ceux du groupe. Si désactivé, seul le reste du groupe s'affiche."
L["Your own frame."] = "Votre propre cadre."
L["Your own groups"] = "Vos propres groupes"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "Votre propre disposition sur ce personnage. Si désactivé, les sorts de ce personnage s'affichent là où le jeu les place, toujours avec l'apparence DaylightUI. Enregistré pour ce personnage."
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "Votre propre tuile se place avec celles du raid. Si désactivé, seul le reste du raid s'affiche."
L["Your party and raid as square tiles under you, dispels easy to spot."] = "Votre groupe et votre raid en tuiles carrées sous vous, avec les dissipations faciles à repérer."
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "Votre groupe : des barres comme votre propre cadre, ou des tuiles carrées. Réglez leur alignement, ce qui s'affiche, et déplacez-les d'un bloc en mode déverrouillage."
L["Your pet"] = "Votre familier"
L["Your pet or minion."] = "Votre familier ou serviteur."
L["Your pet's damage"] = "Les dégâts de votre familier"
L["Your pet's or totem's hits too."] = "Les coups de votre familier ou de vos totems aussi."
L["Your picks are saved into %s."] = "Vos choix sont enregistrés dans %s."
L["Your portrait ring, or your name tab without a portrait, turns red while you're in combat."] = "L'anneau de votre portrait, ou votre onglet de nom sans portrait, devient rouge quand vous êtes en combat."
L["Your priority quest is the one the marker and arrow lead to."] = "Votre quête prioritaire est celle vers laquelle mènent le marqueur et la flèche."
L["Your profession's recipes in one window, in DaylightUI style."] = "Les recettes de votre métier dans une seule fenêtre, au style DaylightUI."
L["Your quest tracker."] = "Votre suivi de quêtes."
L["Your quests in the DaylightUI look, with item buttons and smooth motion."] = "Vos quêtes à l'apparence DaylightUI, avec boutons d'objets et animations fluides."
L["Your role"] = "Votre rôle"
L["Your setup"] = "Votre configuration"
L["Your shots don't land critical hits yet."] = "Vos tirs n'infligent pas encore de coups critiques."
L["Your spellbook and talents in one window, in DaylightUI style."] = "Votre grimoire et vos talents dans une seule fenêtre, au style DaylightUI."
L["Your spells don't land critical hits yet."] = "Vos sorts n'infligent pas encore de coups critiques."
L["Your target's cast bar fills from the right. Not while it sits inside the frame."] = "La barre de sorts de votre cible se remplit depuis la droite. Pas lorsqu'elle est placée dans le cadre."
L["Your target's casts, while they last."] = "Les incantations de votre cible, tant qu'elles durent."
L["Your unit frames, shown here with sample units so you can see each choice."] = "Vos cadres d'unité, affichés ici avec des unités fictives pour que vous voyiez chaque choix."
L["Your watched quests, under the info panel. Move it in unlock mode."] = "Vos quêtes suivies, sous le panneau d'informations. Déplacez-le en mode déverrouillage."
L["Your x, y position at the top of the map. Blank in dungeons and raids."] = "Votre position x, y en haut de la carte. Vide en donjon et en raid."
L["Your x, y position at the top of the minimap. Blank in dungeons and raids."] = "Votre position x, y en haut de la minicarte. Vide en donjon et en raid."
L["Zeppelin to %s"] = "Zeppelin pour %s"
L["Zone"] = "Zone"
L["Zone name color"] = "Couleur du nom de zone"
L["Zone name size"] = "Taille du nom de zone"
L["Zone names"] = "Noms de zone"
L["Zone names in capitals in the quest log"] = "Noms de zones en majuscules dans le journal des quêtes"
L["Zone order"] = "Ordre des zones"
L["Zone title animation"] = "Animation du titre de zone"
L["Zoom"] = "Zoom"
L["Zzz on your portrait ring while you rest in an inn or city."] = "Des Zzz sur l'anneau de votre portrait quand vous vous reposez dans une auberge ou une ville."
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were."] = "[G] pour Général, [T] pour Commerce, [G] pour guilde (en vert de guilde), [P] pour groupe, [S] pour dire, [Y] pour crier, [W] pour chuchotements. Les lignes déjà dans la discussion restent telles quelles."
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were. A chat tab's Show window sets your own tags."] = "[G] pour Général, [T] pour Commerce, [G] pour guilde (en vert de guilde), [P] pour groupe, [S] pour dire, [Y] pour crier, [W] pour chuchotements. Les lignes déjà dans la discussion restent telles quelles. La fenêtre Afficher d'un onglet définit vos propres étiquettes."
L["\"Kicked by\" and the player's name in their class color, beside the cast bar for a moment."] = "« Interrompu par » et le nom du joueur dans la couleur de sa classe, à côté de la barre de sorts pendant un instant."
L["\"Kicked by\" and the player's name in their class color, beside the target's or focus's cast bar for a moment."] = "« Interrompu par » et le nom du joueur dans la couleur de sa classe, à côté de la barre de sorts de la cible ou de la focalisation pendant un instant."
L["\"You create...\" and other crafting messages."] = "« Vous créez... » et autres messages d'artisanat."
L["\"You receive loot\" lines and other loot messages."] = "Les lignes « Vous recevez le butin » et autres messages de butin."
L["\"Your skill in Tailoring has increased\" and the like."] = "« Votre compétence en Couture augmente » et autres messages semblables."
